/* â”€â”€ Focus & Disabled Defaults â”€â”€ */

button:focus-visible,
input:focus-visible,
select:focus-visible,
[role="button"]:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

button:disabled,
input:disabled,
