/* â”€â”€ LoginPage Component â”€â”€ */

export default function LoginPage({ onLoginSuccess }) {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  async function handleSignIn(e) {
    e.preventDefault();
    if (loading) return;

    setLoading(true);
    setError('');

    try {
      const response = await fetch('/api/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: username.trim(), password }),
      });
      const data = await response.json().catch(() => ({}));

      if (!response.ok) {
        throw new Error(data.error || 'Unable to sign in');
      }

      if (!data.token || !data.user) {
        throw new Error('Login response was missing session data');
      }

      onLoginSuccess?.(data.user, data.token);
    } catch (err) {
      setError(err.message || 'Unable to sign in');
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="page-container login-page">

      {/* â”€â”€ LEFT: LOGIN CARD â”€â”€ */}
      <div className="left-panel">
        <div className="glow-blob glow-blob-1" />
        <div className="glow-blob glow-blob-2" />

        <div className="glass-card">
          <div className="card-header">
            <h1 className="card-title">Welcome</h1>
            <p className="card-subtitle">Please enter your credentials below</p>
          </div>

          <form onSubmit={handleSignIn}>
            {error && (
              <div className="login-error" role="alert">
                {error}
              </div>
            )}

            {/* Username */}
            <div className="form-group">
              <label className="form-label" htmlFor="username">Username</label>
              <div className="input-wrapper">
                <input
                  type="text"
                  id="username"
                  className="form-input"
                  placeholder="Enter Username"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  required
                  autoComplete="username"
                  disabled={loading}
                  aria-invalid={Boolean(error)}
                />
              </div>
            </div>

            {/* Password */}
            <div className="form-group">
              <label className="form-label" htmlFor="password">Password</label>
              <div className="input-wrapper">
                <input
                  type={showPassword ? 'text' : 'password'}
                  id="password"
                  className="form-input password-input"
                  placeholder="Enter Password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                  autoComplete="current-password"
                  disabled={loading}
                  aria-invalid={Boolean(error)}
                />
                <button
                  type="button"
                  className="toggle-password"
                  onClick={() => setShowPassword((v) => !v)}
                  disabled={loading}
                  aria-label="Toggle password visibility"
                >
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none"
                    stroke="currentColor" strokeWidth="2"
                    strokeLinecap="round" strokeLinejoin="round">
                    {showPassword ? <EyeClosedIcon /> : <EyeOpenIcon />}
                  </svg>
                </button>
              </div>
            </div>

            {/* Submit */}
            <button type="submit" className="btn-submit" disabled={loading}>
              {loading && <span className="spinner" />}
              <span>{loading ? 'Authenticatingâ€¦' : 'Sign In'}</span>
            </button>
          </form>
        </div>
      </div>

      {/* â”€â”€ RIGHT: BRAND PANEL â”€â”€ */}
      <div className="right-panel">
        <div className="blue-ellipse-bg" />

        <div className="brand-header">
          <h2 className="brand-title">INTERNAL SECURITY</h2>
          <div className="brand-subtitle-row">
            <span className="brand-shield">
              <svg width="42" height="42" viewBox="0 0 24 24">
                <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" fill="#4A7CC7" />
                <path d="M9 11l2 2 4-4" stroke="#fff" strokeWidth="2"
                  strokeLinecap="round" strokeLinejoin="round" fill="none" />
              </svg>
            </span>
            <span className="brand-subtext">MIDDLEWARE HUB</span>
          </div>
        </div>
        <div className="illustration-container">
          <BrandIllustration />
        </div>
      </div>

    </div>
  );
}

