/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   LEFT PANEL
â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.login-page .left-panel {
  flex: 0 0 45%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px;
  background-color: var(--bg-deep);
  position: relative;
  overflow: hidden;
}

/* Glow blobs */
.login-page .glow-blob {
  position: absolute;
  border-radius: 50%;
  filter: blur(70px);
  opacity: 0.55;
  pointer-events: none;
  z-index: 0;
}
.login-page .glow-blob-1 {
  width: 300px;
  height: 300px;
  background-color: var(--blob-purple);
  top: -50px;
  left: -50px;
}
.login-page .glow-blob-2 {
  width: 250px;
  height: 250px;
  background-color: var(--blob-blue);
  bottom: -30px;
  right: -20px;
}


/* â”€â”€ GLASS CARD â”€â”€ */
.login-page .glass-card {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 420px;
  background: var(--bg-card);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--card-border);
  border-radius: 24px;
  padding: 48px 40px;
  box-shadow:
    0 20px 40px rgba(0, 0, 0, 0.35),
    0 1px 10px rgba(91, 46, 166, 0.15);
  transition: box-shadow 0.3s ease;
}
.login-page .glass-card:hover {
  box-shadow:
    0 24px 48px rgba(0, 0, 0, 0.45),
    0 1px 12px rgba(139, 92, 246, 0.2);
}

/* Card header */
.login-page .card-header {
  text-align: center;
  margin-bottom: 36px;
}
.login-page .card-title {
  font-family: var(--font-sans);
  font-size: 28px;
  font-weight: 400;
  text-transform: uppercase;
  color: var(--text-primary);
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}
.login-page .card-subtitle {
  font-family: var(--font-sans);
  font-size: 14px;
  color: var(--text-muted);
  font-weight: 300;
}


/* â”€â”€ FORM â”€â”€ */
.login-page .form-group {
  margin-bottom: 20px;
  position: relative;
}
.login-page .form-label {
  display: block;
  font-family: var(--font-sans);
  font-size: 12px;
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  margin-bottom: 8px;
  padding-left: 4px;
}
.login-page .input-wrapper {
  position: relative;
  display: flex;
  align-items: center;
}
.login-page .form-input {
  width: 100%;
  height: 48px;
  border-radius: 50px;
  border: 1px solid var(--input-border);
  background-color: var(--bg-input);
  padding: 0 24px;
  font-family: var(--font-sans);
  font-size: 14px;
  color: var(--text-primary);
  outline: none;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.login-page .form-input::placeholder {
  color: var(--text-placeholder);
}
.login-page .form-input:focus {
  border-color: var(--input-focus);
  box-shadow: 0 0 0 3px rgba(123, 79, 212, 0.20);
}
.login-page .form-input[aria-invalid="true"] {
  border-color: rgba(226, 75, 74, 0.65);
}
.login-page .form-input:disabled {
  opacity: 0.68;
  cursor: not-allowed;
}
.login-page .password-input {
  padding-right: 52px;
}

.login-page .login-error {
  margin-bottom: 18px;
  padding: 11px 14px;
  border: 1px solid rgba(226, 75, 74, 0.4);
  border-radius: 14px;
  background: rgba(226, 75, 74, 0.11);
  color: #ffb3b2;
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 400;
  line-height: 1.4;
}

/* Eye toggle */
.login-page .toggle-password {
  position: absolute;
  right: 16px;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  cursor: pointer;
  color: var(--icon-color);
  padding: 6px;
  display: flex;
  align-items: center;
  border-radius: 50%;
  transition: color 0.2s ease, background-color 0.2s ease;
}
.login-page .toggle-password:hover {
  color: var(--input-focus);
  background-color: rgba(123, 79, 212, 0.10);
}
.login-page .toggle-password:disabled {
  cursor: not-allowed;
  opacity: 0.58;
}

/* Submit button */
.login-page .btn-submit {
  width: 100%;
  height: 50px;
  border: none;
  border-radius: 50px;
  background: linear-gradient(90deg, var(--btn-from) 0%, var(--btn-to) 100%);
  color: #ffffff;
  font-family: var(--font-sans);
  font-size: 14px;
  font-weight: 400;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow: 0 4px 18px rgba(91, 46, 166, 0.40);
  transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease, opacity 0.2s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-top: 10px;
}
.login-page .btn-submit:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 8px 24px rgba(139, 92, 246, 0.50);
  filter: brightness(1.08);
}
.login-page .btn-submit:active:not(:disabled) {
  transform: translateY(1px);
  box-shadow: 0 2px 10px rgba(91, 46, 166, 0.30);
}
.login-page .btn-submit:disabled {
  opacity: 0.8;
  cursor: default;
}

/* Spinner */
.login-page .spinner {
  border: 3px solid rgba(255, 255, 255, 0.25);
  border-radius: 50%;
  border-top-color: #ffffff;
  width: 18px;
  height: 18px;
  animation: hubLoginSpin 1s linear infinite;
  flex-shrink: 0;
}
@keyframes hubLoginSpin {
  0%   { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   RIGHT PANEL
â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.login-page .right-panel {
  flex: 0 0 55%;
  background-color: var(--bg-panel);
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 60px 80px;
  overflow: hidden;
}

/* Background ellipse */
.login-page .blue-ellipse-bg {
  position: absolute;
  width: 700px;
  height: 700px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--ellipse-from) 0%, var(--ellipse-to) 100%);
  bottom: -150px;
  right: -100px;
  z-index: 0;
  border: 1px solid rgba(255, 255, 255, 0.04);
}

/* Brand heading */
.login-page .brand-header {
  position: relative;
  z-index: 1;
  max-width: 500px;
}
.login-page .brand-title {
  font-family: var(--font-sans);
  font-size: 42px;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.1;
  letter-spacing: -0.02em;
}
.login-page .brand-subtitle-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 8px;
}
.login-page .brand-shield {
  color: var(--panel-blue);
  display: flex;
  align-items: center;
}
.login-page .brand-subtext {
  font-family: var(--font-sans);
  font-size: 32px;
  font-weight: 600;
  color: var(--brand-subtext);
  letter-spacing: 0.02em;
}

/* Illustration */
.login-page .illustration-container {
  position: relative;
  z-index: 1;
  align-self: center;
  width: 100%;
  max-width: 560px;
  height: 380px;
  margin-top: auto;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}
.login-page .brand-illustration {
  width: 100%;
  height: 100%;
}


/* â”€â”€ RESPONSIVE â”€â”€ */
@media (max-width: 768px) {
  .login-page {
    flex-direction: column;
  }
  .login-page .left-panel {
    flex: 0 0 100%;
    width: 100%;
    min-height: 100vh;
    padding: 24px 16px;
  }
  .login-page .glass-card {
    padding: 40px 24px;
    border-radius: 20px;
  }
  .login-page .right-panel {
    display: none;
  }
}

