  font-size: 18px;
  font-weight: 800;
  letter-spacing: -0.5px;
  color: var(--text);
  border-bottom: 1px solid var(--border);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.logo-mark {
  width: 26px;
  height: 26px;
  border-radius: 7px;
  background: linear-gradient(135deg, var(--info), var(--critical));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  box-shadow: 0 0 14px rgba(34, 211, 238, 0.4);
}

.user-block {
  padding: 12px 20px 16px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 8px;
}

.user-name {
  font-weight: 700;
  font-size: 13px;
}

.user-role {
  font-size: 11px;
  color: var(--info);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: 600;
}

.nav-section {
  padding: 8px 12px 4px;
}

.nav-label {
  font-size: 10px;
  color: var(--subtle);
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 0 8px;
  margin-bottom: 4px;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  color: var(--muted);
  font-size: 13px;
  font-weight: 500;
  transition: all 0.15s;
  text-decoration: none;
  margin-bottom: 2px;
  position: relative;
}

.nav-item:hover {
  background: var(--surface2);
  color: var(--text);
}

.nav-item.active {
  background: rgba(34, 211, 238, 0.1);
  color: var(--info);
  border: 1px solid rgba(34, 211, 238, 0.35);
  box-shadow: 0 0 16px rgba(34, 211, 238, 0.12) inset;
}

.nav-badge {
  margin-left: auto;
  background: var(--critical);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 10px;
  box-shadow: 0 0 8px rgba(255, 46, 99, 0.6);
}

.nav-icon {
  width: 16px;
  text-align: center;
  font-size: 14px;
}

.sidebar-footer {
  margin-top: auto;
  padding: 16px 12px 0;
  border-top: 1px solid var(--border);
}

/* â”€â”€ MAIN â”€â”€ */
.main {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* â”€â”€ TOPBAR â”€â”€ */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 28px;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
  position: sticky;
  top: 0;
  z-index: 10;
}

.topbar-left h1 {
  font-size: 16px;
  font-weight: 700;
}

.topbar-left p {
  font-size: 12px;
  color: var(--info);
  margin-top: 1px;
  font-weight: 500;
  letter-spacing: 0.3px;
}

.topbar-actions {
  display: flex;
  gap: 8px;
  align-items: center;
}

.btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s;
  border: 1px solid var(--border);
  background: var(--surface2);
  color: var(--text);
  font-family: inherit;
}

.btn:hover {
  border-color: var(--info);
  color: var(--info);
}

.btn.btn-live {
  border-color: var(--low);
  color: var(--low);
  background: rgba(57, 255, 136, 0.08);
  box-shadow: 0 0 12px rgba(57, 255, 136, 0.15);
}

.btn.btn-live::before {
  content: 'â—';
  font-size: 8px;
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

/* â”€â”€ CONTENT â”€â”€ */
.content {
  padding: 24px 28px;
  flex: 1;
  overflow-y: auto;
}

/* â”€â”€ STAT CARDS ROW â”€â”€ */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 12px;
  margin-bottom: 20px;
}

/* Shared titles & section structures */
.vuln-panel-title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--muted);
  display: flex;
  align-items: center;
  gap: 6px;
  grid-column: 1 / -1;
  margin-bottom: 10px;
}

.section-title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text);
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.section-title::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border);
}

/* Vulnerability Status panel â€” outlined neon style */
.vuln-panel {
  display: flex;
  align-items: stretch;
  gap: 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
}

.outline-card {
  flex: 1;
  border-radius: var(--radius);
  padding: 16px 20px;
  background: rgba(255, 255, 255, 0.015);
  position: relative;
}

.outline-card.outline-critical {
  border: 1.5px solid rgba(255, 46, 99, 0.6);
  box-shadow: 0 0 22px rgba(255, 46, 99, 0.18), inset 0 0 22px rgba(255, 46, 99, 0.04);
}

.outline-card.outline-mitigated {
  border: 1.5px solid rgba(57, 255, 136, 0.6);
  box-shadow: 0 0 22px rgba(57, 255, 136, 0.18), inset 0 0 22px rgba(57, 255, 136, 0.04);
}

.outline-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.outline-value {
  font-size: 34px;
  font-weight: 800;
  letter-spacing: -1.5px;
  line-height: 1;
}

.outline-value.red {
  color: var(--critical);
  text-shadow: 0 0 20px rgba(255, 46, 99, 0.55);
}

.outline-value.green {
  color: var(--low);
  text-shadow: 0 0 20px rgba(57, 255, 136, 0.55);
}

.outline-tag {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: var(--critical);
  text-shadow: 0 0 14px rgba(255, 46, 99, 0.5);
}

.outline-label {
  font-size: 12px;
  color: var(--text);
  font-weight: 600;
  margin-top: 6px;
}

.outline-sub {
  font-size: 11px;
  color: var(--muted);
  margin-top: 2px;
}

.vuln-arrow {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--subtle);
  font-size: 20px;
  padding: 0 4px;
}

/* Ticket Workflow â€” filled solid color tiles */
.stat-card {
  border-radius: var(--radius);
  padding: 16px;
  position: relative;
  overflow: hidden;
  transition: transform 0.15s;
}

.stat-card:hover {
  transform: translateY(-2px);
}

.stat-card.accent-blue {
  background: #2F7DDE;
}

.stat-card.accent-yellow {
  background: #E2A33B;
}

.stat-card.accent-pink {
  background: #E2447F;
}

.stat-card.accent-green-fill {
  background: #3FAE76;
}

.stat-card.accent-grey {
  background: #8A8F98;
}

.stat-label {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.85);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 8px;
}

.stat-value {
  font-size: 30px;
  font-weight: 800;
  letter-spacing: -1px;
  line-height: 1;
  color: #fff;
}

.stat-sub {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.75);
  margin-top: 4px;
}

.stat-icon {
  font-size: 16px;
  color: rgba(255, 255, 255, 0.9);
  margin-top: 10px;
}

/* â”€â”€ SEVERITY DISTRIBUTION â€” arc gauges, no boxes â”€â”€ */
.severity-panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px 20px 18px;
  margin-bottom: 24px;
}

.severity-panel-title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--muted);
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 18px;
}

.severity-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
}

.gauge-card {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.gauge-svg {
  display: block;
}

.gauge-value {
  font-size: 26px;
  font-weight: 800;
  letter-spacing: -1px;
  margin-top: -34px;
}

.gauge-name {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--muted);
  margin-top: 4px;
}

.gauge-critical .gauge-value {
  color: var(--critical);
  text-shadow: 0 0 16px rgba(255, 46, 99, 0.55);
}

.gauge-high .gauge-value {
  color: var(--high);
  text-shadow: 0 0 16px rgba(255, 167, 43, 0.5);
}

.gauge-medium .gauge-value {
  color: var(--medium);
  text-shadow: 0 0 16px rgba(255, 214, 10, 0.45);
}

.gauge-low .gauge-value {
  color: var(--low);
  text-shadow: 0 0 16px rgba(57, 255, 136, 0.5);
}

.gauge-info .gauge-value {
  color: var(--info);
  text-shadow: 0 0 16px rgba(34, 211, 238, 0.45);
}

/* â”€â”€ SEARCH & FILTERS â”€â”€ */
.toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}

.search-wrap {
  flex: 1;
  min-width: 200px;
  position: relative;
}

.search-wrap input {
  width: 100%;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 10px 14px 10px 36px;
  color: var(--text);
  font-size: 13px;
  font-family: inherit;
  outline: none;
  transition: all 0.2s;
}

.search-wrap input:focus {
  border-color: var(--info);
  box-shadow: 0 0 0 3px rgba(34, 211, 238, 0.12);
}

.search-wrap input::placeholder {
  color: var(--subtle);
}

.search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--info);
  font-size: 15px;
}

.filter-chips {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.chip {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 13px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--muted);
  transition: all 0.15s;
  font-family: inherit;
}

.chip:hover {
  border-color: var(--info);
  color: var(--info);
}

.chip.active-chip {
  background: rgba(34, 211, 238, 0.12);
  border-color: var(--info);
  color: var(--info);
  box-shadow: 0 0 14px rgba(34, 211, 238, 0.15);
}

.chip.chip-critical.active-chip {
  background: var(--critical-bg);
  border-color: var(--critical);
  color: var(--critical);
  box-shadow: 0 0 14px rgba(255, 46, 99, 0.2);
}

.chip.chip-high.active-chip {
  background: var(--high-bg);
  border-color: var(--high);
  color: var(--high);
  box-shadow: 0 0 14px rgba(255, 167, 43, 0.2);
}

.chip.chip-low.active-chip {
  background: var(--low-bg);
  border-color: var(--low);
  color: var(--low);
  box-shadow: 0 0 14px rgba(57, 255, 136, 0.2);
}

.chip-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
}

.dot-all {
  background: var(--info);
  box-shadow: 0 0 6px var(--info);
}

.dot-critical {
  background: var(--critical);
  box-shadow: 0 0 6px var(--critical);
}

.dot-high {
  background: var(--high);
  box-shadow: 0 0 6px var(--high);
}

.dot-medium {
  background: var(--medium);
  box-shadow: 0 0 6px var(--medium);
}

.dot-low {
  background: var(--low);
  box-shadow: 0 0 6px var(--low);
}

.result-count {
  margin-left: auto;
  font-size: 12px;
  color: var(--muted);
  white-space: nowrap;
  font-weight: 500;
}

/* â”€â”€ TABLE â”€â”€ */
.table-wrap {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
}

table {
  width: 100%;
  border-collapse: collapse;
}

thead tr {
  background: var(--surface2);
  border-bottom: 1px solid var(--border);
}

th {
  padding: 12px 16px;
  text-align: left;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.7px;
  color: var(--info);
  white-space: nowrap;
  user-select: none;
  cursor: pointer;
  opacity: 0.85;
}

th:hover {
  opacity: 1;
}

tbody tr {
  border-bottom: 1px solid var(--border);
  transition: background 0.1s;
  cursor: pointer;
}

tbody tr:last-child {
  border-bottom: none;
}

tbody tr:hover {
  background: var(--surface2);
}

td {
  padding: 14px 16px;
  font-size: 13px;
  vertical-align: middle;
}

.td-id {
  font-family: 'JetBrains Mono', monospace;
  font-size: 12px;
  color: var(--info);
  font-weight: 600;
}

.td-company {
  color: var(--text);
  font-size: 12px;
  font-weight: 500;
}

.sev-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 11px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  white-space: nowrap;
}

.badge-critical {
  background: var(--critical-bg);
  color: var(--critical);
  border: 1px solid rgba(255, 46, 99, 0.45);
  box-shadow: 0 0 10px rgba(255, 46, 99, 0.15);
}

.badge-high {
  background: var(--high-bg);
  color: var(--high);
  border: 1px solid rgba(255, 167, 43, 0.4);
}

.badge-medium {
  background: var(--medium-bg);
  color: var(--medium);
  border: 1px solid rgba(255, 214, 10, 0.35);
}

.badge-low {
  background: var(--low-bg);
  color: var(--low);
  border: 1px solid rgba(57, 255, 136, 0.4);
}

.finding-name {
  font-weight: 600;
  color: var(--text);
  margin-bottom: 2px;
}

.finding-owner {
  font-size: 11px;
  color: var(--subtle);
}

.count-cell {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 12px;
  font-weight: 600;
  color: var(--text);
}

.count-icon {
  color: var(--info);
  font-size: 13px;
}

.cve-tag {
  display: inline-flex;
  align-items: center;
  padding: 3px 9px;
  border-radius: 5px;
  font-size: 11px;
  font-weight: 700;
  font-family: 'JetBrains Mono', monospace;
  margin-right: 4px;
}

.cve-red {
  background: var(--critical-bg);
  color: var(--critical);
  border: 1px solid rgba(255, 46, 99, 0.35);
}

.cve-grey {
  background: rgba(155, 163, 184, 0.08);
  color: var(--muted);
  border: 1px solid var(--border);
}

.cve-none {
  color: var(--subtle);
  font-size: 12px;
}

.date-cell {
  font-family: 'JetBrains Mono', monospace;
  font-size: 12px;
  color: var(--muted);
}

.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 13px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  white-space: nowrap;
}

.status-new {
  background: rgba(34, 211, 238, 0.14);
  color: var(--info);
  border: 1px solid rgba(34, 211, 238, 0.4);
  box-shadow: 0 0 10px rgba(34, 211, 238, 0.15);
}

.status-inprogress {
  background: rgba(255, 214, 10, 0.14);
  color: var(--medium);
  border: 1px solid rgba(255, 214, 10, 0.4);
  box-shadow: 0 0 10px rgba(255, 214, 10, 0.15);
}

.status-resolved {
  background: rgba(57, 255, 136, 0.14);
  color: var(--low);
  border: 1px solid rgba(57, 255, 136, 0.4);
  box-shadow: 0 0 10px rgba(57, 255, 136, 0.15);
}

.status-feedback {
  background: rgba(196, 110, 255, 0.14);
  color: var(--purple);
  border: 1px solid rgba(196, 110, 255, 0.4);
  box-shadow: 0 0 10px rgba(196, 110, 255, 0.15);
}

.row-action {
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 13px;
  transition: all 0.15s;
}

.row-action:hover {
  border-color: var(--info);
  color: var(--info);
  box-shadow: 0 0 10px rgba(34, 211, 238, 0.2);
}

/* â”€â”€ PAGINATION â”€â”€ */
.pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px;
  border-top: 1px solid var(--border);
  background: var(--surface2);
}

.pagination-info {
  font-size: 12px;
  color: var(--muted);
  font-weight: 500;
}

.pagination-controls {
  display: flex;
  align-items: center;
  gap: 6px;
}

.page-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: transparent;
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s;
  font-family: inherit;
}

.page-btn:hover {
  border-color: var(--info);
  color: var(--info);
}

.page-btn.active-page {
  background: var(--info);
  border-color: var(--info);
  color: #04141A;
  box-shadow: 0 0 14px rgba(34, 211, 238, 0.4);
}

.per-page {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--muted);
}

.per-page select {
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text);
  padding: 5px 8px;
  font-size: 12px;
  font-family: inherit;
  outline: none;
  cursor: pointer;
}

@import 'base.css';
@import 'layout.css';
@import 'vulnerability_status.css';
@import 'ticket_workflow.css';
@import 'severity_distribution.css';
@import 'findings_table.css';

/* ==========================================================================
   TABLE OF CONTENTS
   ==========================================================================
   1. BASE STYLES & VARIABLES
   2. PAGE LAYOUT (Sidebar & Header)
   3. VULNERABILITY STATUS
   4. TICKET WORKFLOW
   5. SEVERITY & RISK DISTRIBUTION
   6. FINDINGS TOOLBAR & FILTERS
   7. FINDINGS TABLE & BADGES
   8. PAGINATION & UTILITIES
   ========================================================================== */

/* ==========================================================================
   1. BASE STYLES & VARIABLES
   ========================================================================== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg:          #08090D;
  --surface:     #12141C;
  --surface2:    #181B26;
  --border:      #2A2E3E;
  --border-glow: #3A3F56;
  --text:        #F4F6FB;
  --muted:       #9BA3B8;
  --subtle:      #5C6378;

  --critical:    #FF2E63;
  --high:        #FFA72B;
  --medium:      #FFD60A;
  --low:         #39FF88;
  --info:        #22D3EE;
  --purple:      #C46EFF;

  --critical-bg: rgba(255, 46, 99, 0.14);
  --high-bg:     rgba(255, 167, 43, 0.14);
  --medium-bg:   rgba(255, 214, 10, 0.12);
  --low-bg:      rgba(57, 255, 136, 0.12);
  --info-bg:     rgba(34, 211, 238, 0.12);

  --radius:      12px;
  --radius-sm:   7px;
}

body {
  font-family: 'Inter', sans-serif;
  background: var(--bg);
  background-image:
    radial-gradient(circle at 15% 0%, rgba(255, 46, 99, 0.06), transparent 40%),
    radial-gradient(circle at 85% 10%, rgba(34, 211, 238, 0.06), transparent 40%);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  font-size: 14px;
  line-height: 1.5;
}

/* Custom Scrollbar */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--border-glow);
}

/* ==========================================================================
   2. PAGE LAYOUT (Sidebar & Header)
   ========================================================================== */
/* Sidebar */
.sidebar {
  width: 220px;
  min-height: 100vh;
  background: var(--surface);
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  padding: 20px 0;
  flex-shrink: 0;
  position: sticky;
  top: 0;
  height: 100vh;
}

.logo {
  padding: 0 20px 24px;
  font-size: 18px;
  font-weight: 800;
  letter-spacing: -0.5px;
  color: var(--text);
  border-bottom: 1px solid var(--border);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.logo-mark {
  width: 26px;
  height: 26px;
  border-radius: 7px;
  background: linear-gradient(135deg, var(--info), var(--critical));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  box-shadow: 0 0 14px rgba(34, 211, 238, 0.4);
}

.user-block {
  padding: 12px 20px 16px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 8px;
}

.user-name {
  font-weight: 700;
  font-size: 13px;
}

.user-role {
  font-size: 11px;
  color: var(--info);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: 600;
}

.nav-section {
  padding: 8px 12px 4px;
}

.nav-label {
  font-size: 10px;
  color: var(--subtle);
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 0 8px;
  margin-bottom: 4px;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  color: var(--muted);
  font-size: 13px;
  font-weight: 500;
  transition: all 0.15s;
  text-decoration: none;
  margin-bottom: 2px;
  position: relative;
}

.nav-item:hover {
  background: var(--surface2);
  color: var(--text);
}

.nav-item.active {
  background: rgba(34, 211, 238, 0.1);
  color: var(--info);
  border: 1px solid rgba(34, 211, 238, 0.35);
  box-shadow: 0 0 16px rgba(34, 211, 238, 0.12) inset;
}

.nav-badge {
  margin-left: auto;
  background: var(--critical);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 10px;
  box-shadow: 0 0 8px rgba(255, 46, 99, 0.6);
}

.nav-icon {
  width: 16px;
  text-align: center;
  font-size: 14px;
}

.sidebar-footer {
  margin-top: auto;
  padding: 16px 12px 0;
  border-top: 1px solid var(--border);
}

/* Main Area & Header */
.main {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 28px;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
  position: sticky;
  top: 0;
  z-index: 10;
}

.topbar-left h1 {
  font-size: 16px;
  font-weight: 700;
}

.topbar-left p {
  font-size: 12px;
  color: var(--info);
  margin-top: 1px;
  font-weight: 500;
  letter-spacing: 0.3px;
}

.topbar-actions {
  display: flex;
  gap: 8px;
  align-items: center;
}

.btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s;
  border: 1px solid var(--border);
  background: var(--surface2);
  color: var(--text);
  font-family: inherit;
}

.btn:hover {
  border-color: var(--info);
  color: var(--info);
}

.btn.btn-live {
  border-color: var(--low);
  color: var(--low);
  background: rgba(57, 255, 136, 0.08);
  box-shadow: 0 0 12px rgba(57, 255, 136, 0.15);
}

.btn.btn-live::before {
  content: 'â—';
  font-size: 8px;
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

.content {
  padding: 24px 28px;
  flex: 1;
  overflow-y: auto;
}

.section-title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text);
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.section-title::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border);
}

/* ==========================================================================
   3. VULNERABILITY STATUS
   ========================================================================== */
.vuln-panel-title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--muted);
  display: flex;
  align-items: center;
  gap: 6px;
  grid-column: 1 / -1;
  margin-bottom: 10px;
}

.vuln-panel {
  display: flex;
  align-items: stretch;
  gap: 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
}

.outline-card {
  flex: 1;
  border-radius: var(--radius);
  padding: 16px 20px;
  background: rgba(255, 255, 255, 0.015);
  position: relative;
}

.outline-card.outline-critical {
  border: 1.5px solid rgba(255, 46, 99, 0.6);
  box-shadow: 0 0 22px rgba(255, 46, 99, 0.18), inset 0 0 22px rgba(255, 46, 99, 0.04);
}

.outline-card.outline-mitigated {
  border: 1.5px solid rgba(57, 255, 136, 0.6);
  box-shadow: 0 0 22px rgba(57, 255, 136, 0.18), inset 0 0 22px rgba(57, 255, 136, 0.04);
}

.outline-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.outline-value {
  font-size: 34px;
  font-weight: 800;
  letter-spacing: -1.5px;
  line-height: 1;
}

.outline-value.red {
  color: var(--critical);
  text-shadow: 0 0 20px rgba(255, 46, 99, 0.55);
}

.outline-value.green {
  color: var(--low);
  text-shadow: 0 0 20px rgba(57, 255, 136, 0.55);
}

.outline-tag {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: var(--critical);
  text-shadow: 0 0 14px rgba(255, 46, 99, 0.5);
}

.outline-label {
  font-size: 12px;
  color: var(--text);
  font-weight: 600;
  margin-top: 6px;
}

.outline-sub {
  font-size: 11px;
  color: var(--muted);
  margin-top: 2px;
}

.vuln-arrow {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--subtle);
  font-size: 20px;
  padding: 0 4px;
}

/* ==========================================================================
   4. TICKET WORKFLOW
   ========================================================================== */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 12px;
  margin-bottom: 20px;
}

.stat-card {
  border-radius: var(--radius);
  padding: 16px;
  position: relative;
  overflow: hidden;
  transition: transform 0.15s;
}

.stat-card:hover {
  transform: translateY(-2px);
}

.stat-card.accent-blue {
  background: #2F7DDE;
}

.stat-card.accent-yellow {
  background: #E2A33B;
}

.stat-card.accent-pink {
  background: #E2447F;
}

.stat-card.accent-green-fill {
  background: #3FAE76;
}

.stat-card.accent-grey {
  background: #8A8F98;
}

.stat-label {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.85);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 8px;
}

.stat-value {
  font-size: 30px;
  font-weight: 800;
  letter-spacing: -1px;
  line-height: 1;
  color: #fff;
}

.stat-sub {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.75);
  margin-top: 4px;
}

.stat-icon {
  font-size: 16px;
  color: rgba(255, 255, 255, 0.9);
  margin-top: 10px;
}

/* ==========================================================================
   5. SEVERITY & RISK DISTRIBUTION
   ========================================================================== */
.severity-panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px 20px 18px;
  margin-bottom: 24px;
}

.severity-panel-title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--muted);
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 18px;
}

.severity-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
}

.gauge-card {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.gauge-svg {
  display: block;
}

.gauge-value {
  font-size: 26px;
  font-weight: 800;
  letter-spacing: -1px;
  margin-top: -34px;
}

.gauge-name {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--muted);
  margin-top: 4px;
}

.gauge-critical .gauge-value {
  color: var(--critical);
  text-shadow: 0 0 16px rgba(255, 46, 99, 0.55);
}

.gauge-high .gauge-value {
  color: var(--high);
  text-shadow: 0 0 16px rgba(255, 167, 43, 0.5);
}

.gauge-medium .gauge-value {
  color: var(--medium);
  text-shadow: 0 0 16px rgba(255, 214, 10, 0.45);
}

.gauge-low .gauge-value {
  color: var(--low);
  text-shadow: 0 0 16px rgba(57, 255, 136, 0.5);
}

.gauge-info .gauge-value {
  color: var(--info);
  text-shadow: 0 0 16px rgba(34, 211, 238, 0.45);
}

/* ==========================================================================
   6. FINDINGS TOOLBAR & FILTERS
   ========================================================================== */
.toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}

.search-wrap {
  flex: 1;
  min-width: 200px;
  position: relative;
}

.search-wrap input {
  width: 100%;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 10px 14px 10px 36px;
  color: var(--text);
  font-size: 13px;
  font-family: inherit;
  outline: none;
  transition: all 0.2s;
}

.search-wrap input:focus {
  border-color: var(--info);
  box-shadow: 0 0 0 3px rgba(34, 211, 238, 0.12);
}

.search-wrap input::placeholder {
  color: var(--subtle);
}

.search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--info);
  font-size: 15px;
}

.filter-chips {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.chip {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 13px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--muted);
  transition: all 0.15s;
  font-family: inherit;
}

.chip:hover {
  border-color: var(--info);
  color: var(--info);
}

.chip.active-chip {
  background: rgba(34, 211, 238, 0.12);
  border-color: var(--info);
  color: var(--info);
  box-shadow: 0 0 14px rgba(34, 211, 238, 0.15);
}

.chip.chip-critical.active-chip {
  background: var(--critical-bg);
  border-color: var(--critical);
  color: var(--critical);
  box-shadow: 0 0 14px rgba(255, 46, 99, 0.2);
}

.chip.chip-high.active-chip {
  background: var(--high-bg);
  border-color: var(--high);
  color: var(--high);
  box-shadow: 0 0 14px rgba(255, 167, 43, 0.2);
}

.chip.chip-low.active-chip {
  background: var(--low-bg);
  border-color: var(--low);
  color: var(--low);
  box-shadow: 0 0 14px rgba(57, 255, 136, 0.2);
}

.chip-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
}

.dot-all {
  background: var(--info);
  box-shadow: 0 0 6px var(--info);
}

.dot-critical {
  background: var(--critical);
  box-shadow: 0 0 6px var(--critical);
}

.dot-high {
  background: var(--high);
  box-shadow: 0 0 6px var(--high);
}

.dot-medium {
  background: var(--medium);
  box-shadow: 0 0 6px var(--medium);
}

.dot-low {
  background: var(--low);
  box-shadow: 0 0 6px var(--low);
}

.result-count {
  margin-left: auto;
  font-size: 12px;
  color: var(--muted);
  white-space: nowrap;
  font-weight: 500;
}

/* ==========================================================================
   7. FINDINGS TABLE & BADGES
   ========================================================================== */
.table-wrap {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
}

table {
  width: 100%;
  border-collapse: collapse;
}

thead tr {
  background: var(--surface2);
  border-bottom: 1px solid var(--border);
}

th {
  padding: 12px 16px;
  text-align: left;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.7px;
  color: var(--info);
  white-space: nowrap;
  user-select: none;
  cursor: pointer;
  opacity: 0.85;
}

th:hover {
  opacity: 1;
}

tbody tr {
  border-bottom: 1px solid var(--border);
  transition: background 0.1s;
  cursor: pointer;
}

tbody tr:last-child {
  border-bottom: none;
}

tbody tr:hover {
  background: var(--surface2);
}

td {
  padding: 14px 16px;
  font-size: 13px;
  vertical-align: middle;
}

.td-id {
  font-family: 'JetBrains Mono', monospace;
  font-size: 12px;
  color: var(--info);
  font-weight: 600;
}

.td-company {
  color: var(--text);
  font-size: 12px;
  font-weight: 500;
}

.sev-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 11px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  white-space: nowrap;
}

.badge-critical {
  background: var(--critical-bg);
  color: var(--critical);
  border: 1px solid rgba(255, 46, 99, 0.45);
  box-shadow: 0 0 10px rgba(255, 46, 99, 0.15);
}

.badge-high {
  background: var(--high-bg);
  color: var(--high);
  border: 1px solid rgba(255, 167, 43, 0.4);
}

.badge-medium {
  background: var(--medium-bg);
  color: var(--medium);
  border: 1px solid rgba(255, 214, 10, 0.35);
}

.badge-low {
  background: var(--low-bg);
  color: var(--low);
  border: 1px solid rgba(57, 255, 136, 0.4);
}

.finding-name {
  font-weight: 600;
  color: var(--text);
  margin-bottom: 2px;
}

.finding-owner {
  font-size: 11px;
  color: var(--subtle);
}

.count-cell {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 12px;
  font-weight: 600;
  color: var(--text);
}

.count-icon {
  color: var(--info);
  font-size: 13px;
}

.cve-tag {
  display: inline-flex;
  align-items: center;
  padding: 3px 9px;
  border-radius: 5px;
  font-size: 11px;
  font-weight: 700;
  font-family: 'JetBrains Mono', monospace;
  margin-right: 4px;
}

.cve-red {
  background: var(--critical-bg);
  color: var(--critical);
  border: 1px solid rgba(255, 46, 99, 0.35);
}

.cve-grey {
  background: rgba(155, 163, 184, 0.08);
  color: var(--muted);
  border: 1px solid var(--border);
}

.cve-none {
  color: var(--subtle);
  font-size: 12px;
}

.date-cell {
  font-family: 'JetBrains Mono', monospace;
  font-size: 12px;
  color: var(--muted);
}

.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 13px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  white-space: nowrap;
}

.status-new {
  background: rgba(34, 211, 238, 0.14);
  color: var(--info);
  border: 1px solid rgba(34, 211, 238, 0.4);
  box-shadow: 0 0 10px rgba(34, 211, 238, 0.15);
}

.status-inprogress {
  background: rgba(255, 214, 10, 0.14);
  color: var(--medium);
  border: 1px solid rgba(255, 214, 10, 0.4);
  box-shadow: 0 0 10px rgba(255, 214, 10, 0.15);
}

.status-resolved {
  background: rgba(57, 255, 136, 0.14);
  color: var(--low);
  border: 1px solid rgba(57, 255, 136, 0.4);
  box-shadow: 0 0 10px rgba(57, 255, 136, 0.15);
}

.status-feedback {
  background: rgba(196, 110, 255, 0.14);
  color: var(--purple);
  border: 1px solid rgba(196, 110, 255, 0.4);
  box-shadow: 0 0 10px rgba(196, 110, 255, 0.15);
}

.row-action {
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 13px;
  transition: all 0.15s;
}

.row-action:hover {
  border-color: var(--info);
  color: var(--info);
  box-shadow: 0 0 10px rgba(34, 211, 238, 0.2);
}

/* ==========================================================================
   8. PAGINATION & UTILITIES
   ========================================================================== */
.pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px;
  border-top: 1px solid var(--border);
  background: var(--surface2);
}

.pagination-info {
  font-size: 12px;
  color: var(--muted);
  font-weight: 500;
}

.pagination-controls {
  display: flex;
  align-items: center;
  gap: 6px;
}

.page-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: transparent;
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s;
  font-family: inherit;
}

.page-btn:hover {
  border-color: var(--info);
  color: var(--info);
}

.page-btn.active-page {
  background: var(--info);
  border-color: var(--info);
  color: #04141A;
  box-shadow: 0 0 14px rgba(34, 211, 238, 0.4);
}

.per-page {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--muted);
}

.per-page select {
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text);
  padding: 5px 8px;
  font-size: 12px;
  font-family: inherit;
  outline: none;
  cursor: pointer;
}

