/* â”€â”€ Dashboard Overview Cards (Neon) â”€â”€ */

.dashboard-soc-overview-new {
  display: flex;
  flex-direction: column;
  gap: 20px;
  margin-bottom: 24px;
}

.soc-top-row {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 16px;
}

/* â”€â”€ STAT CARDS ROW â”€â”€ */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 12px;
  margin-bottom: 20px;
}
.ticket-grid {
  grid-template-columns: repeat(5, 1fr);
  margin-bottom: 0;
  height: calc(100% - 28px);
}

/* Vulnerability Status panel â€” outlined neon style */
.vuln-panel {
  display: flex; 
  align-items: stretch; 
  gap: 16px;
  background: var(--surface, #13161e);
  border: 1px solid var(--border, #2a3145);
  border-radius: var(--radius, 8px);
  padding: 16px;
}
.vuln-panel-title {
  font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.8px;
  color: var(--muted, #8A8F98); display: flex; align-items: center; gap: 6px;
  grid-column: 1 / -1; margin-bottom: 10px;
}

.outline-card {
  flex: 1;
  border-radius: var(--radius, 8px);
  padding: 16px 20px;
  background: rgba(255,255,255,0.015);
  position: relative;
}
.outline-card.outline-critical {
  border: 1.5px solid rgba(255,46,99,0.6);
  box-shadow: 0 0 22px rgba(255,46,99,0.18), inset 0 0 22px rgba(255,46,99,0.04);
}
.outline-card.outline-mitigated {
  border: 1.5px solid rgba(57,255,136,0.6);
  box-shadow: 0 0 22px rgba(57,255,136,0.18), inset 0 0 22px rgba(57,255,136,0.04);
}

.outline-top { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
.outline-value { font-size: 34px; font-weight: 800; letter-spacing: -1.5px; line-height: 1; }
.outline-value.red { color: var(--critical, #FF2E63); text-shadow: 0 0 20px rgba(255,46,99,0.55); }
.outline-value.green { color: var(--low, #39FF88); text-shadow: 0 0 20px rgba(57,255,136,0.55); }
.outline-tag {
  font-size: 12px; font-weight: 800; letter-spacing: 0.5px; text-transform: uppercase;
  color: var(--critical, #FF2E63); text-shadow: 0 0 14px rgba(255,46,99,0.5);
}
.outline-label { font-size: 12px; color: var(--text, #E2E8F0); font-weight: 600; margin-top: 6px; }
.outline-sub { font-size: 11px; color: var(--muted, #8A8F98); margin-top: 2px; }

.vuln-arrow { display: flex; align-items: center; justify-content: center; color: var(--subtle, #4A5060); font-size: 20px; padding: 0 4px; }

/* Ticket Workflow â€” filled solid color tiles */
.stat-card {
  border-radius: var(--radius, 8px);
  padding: 16px;
  position: relative;
  overflow: hidden;
  transition: transform 0.15s;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.stat-card:hover { transform: translateY(-2px); }

.stat-card.accent-blue   { background: #2F7DDE; }
.stat-card.accent-yellow { background: #E2A33B; }
.stat-card.accent-pink   { background: #E2447F; }
.stat-card.accent-green-fill { background: #3FAE76; }
.stat-card.accent-grey   { background: #8A8F98; }

.stat-label { font-size: 11px; color: rgba(255,255,255,0.85); font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 8px; }
.stat-value { font-size: 30px; font-weight: 800; letter-spacing: -1px; line-height: 1; color: #fff; }
.stat-sub { font-size: 11px; color: rgba(255,255,255,0.75); margin-top: 4px; }
.stat-icon { color: rgba(255,255,255,0.9); margin-top: 10px; display: flex; justify-content: flex-end; }

/* â”€â”€ SECTION TITLE â”€â”€ */
.section-title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text, #E2E8F0);
  margin-bottom: 12px;
  display: flex; align-items: center; gap: 8px;
}
.section-title::after { content: ''; flex: 1; height: 1px; background: var(--border, #2a3145); }

/* â”€â”€ SEVERITY DISTRIBUTION â€” arc gauges, no boxes â”€â”€ */
.severity-panel {
  background: var(--surface, #13161e);
  border: 1px solid var(--border, #2a3145);
  border-radius: var(--radius, 8px);
  padding: 22px 20px 18px;
  margin-bottom: 24px;
}
.severity-panel-title {
  font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.8px;
  color: var(--muted, #8A8F98); display: flex; align-items: center; gap: 6px;
  margin-bottom: 18px;
}

.severity-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
}

.gauge-card { display: flex; flex-direction: column; align-items: center; }
.gauge-svg { display: block; }
.gauge-value {
  font-size: 26px; font-weight: 800; letter-spacing: -1px;
  margin-top: -34px;
}
.gauge-name {
  font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.6px;
  color: var(--muted, #8A8F98); margin-top: 4px;
}

.gauge-critical .gauge-value { color: var(--critical, #FF2E63); text-shadow: 0 0 16px rgba(255,46,99,0.55); }
.gauge-high     .gauge-value { color: var(--high, #FFA72B);     text-shadow: 0 0 16px rgba(255,167,43,0.5); }
.gauge-medium   .gauge-value { color: var(--medium, #FFD60A);   text-shadow: 0 0 16px rgba(255,214,10,0.45); }
.gauge-low      .gauge-value { color: var(--low, #39FF88);      text-shadow: 0 0 16px rgba(57,255,136,0.5); }
.gauge-info     .gauge-value { color: var(--info, #22D3EE);     text-shadow: 0 0 16px rgba(34,211,238,0.45); }

/* â”€â”€ Responsive â”€â”€ */
@media (max-width: 1100px) {
  .soc-top-row {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 820px) {
  .vuln-panel {
    flex-direction: column;
  }
  .vuln-arrow {
    transform: rotate(90deg);
  }
  .ticket-grid {
    grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  }
  .severity-grid {
    grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
    gap: 20px;
  }
}
@media (max-width: 640px) {
  .ticket-grid {
    grid-template-columns: 1fr;
  }
  .severity-grid {
    grid-template-columns: 1fr;
  }
}

Args.TargetContent:
/* â”€â”€ Dashboard Overview Cards â”€â”€ */

.dashboard-soc-overview {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-lg);
  margin-bottom: var(--space-lg);
}

/* â”€â”€ Card Shell â”€â”€ */

.soc-card {
  position: relative;
  min-width: 0;
  overflow: hidden;
  padding: var(--space-lg);
  border: 1px solid var(--border);
  border-radius: var(--rounded-md);
  background: color-mix(in oklab, oklch(21% .034 264.665) 80%, transparent);
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
}

.soc-card-vulnerability {
  border-color: var(--border-strong);
}

.soc-card-workflow {
  border-color: var(--border-strong);
}

.soc-card-severity {
  grid-column: 1 / -1;
}

/* â”€â”€ Card Header â”€â”€ */

.soc-card-header {
  position: relative;
  z-index: 1;
  margin-bottom: var(--space-md);
}

.soc-card-title-row {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.soc-card-title-row > svg {
  flex: 0 0 auto;
  color: var(--primary);
  width: 1.3rem;
  height: 1.3rem;
}

.soc-card-vulnerability .soc-card-title-row > svg {
  color: var(--high-text);
}

.soc-card-workflow .soc-card-title-row > svg {
  color: var(--info-text);
}

.soc-card-severity .soc-card-title-row > svg {
  color: var(--primary);
}

.soc-card-header h2 {
  margin: 0;
  color: var(--text-main);
  font-size: 0.92rem;
  font-family: var(--font-sans);
  line-height: 1.25;
  font-weight: var(--font-weight-uppercase);
  letter-spacing: 0.04em;
  text-transform: var(--text-transform-uppercase);
}

.soc-card-header p {
  margin: var(--space-xs) 0 0;
  color: var(--text-muted);
  font-size: 0.82rem;
  font-weight: var(--font-weight-medium);
}

/* â”€â”€ Vulnerability Flow â”€â”€ */

.vulnerability-flow {
  position: relative;
  z-index: 1;
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 2.3rem 1fr;
  align-items: center;
  gap: var(--space-xs);
}

.vulnerability-count-box {
  min-width: 0;
  height: 100%;
  padding: var(--space-md) var(--space-lg);
  border: 1px solid var(--border-subtle);
  border-radius: var(--rounded-sm);
  background: var(--bg-subtle);
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: var(--space-xs);
}

.vulnerability-count-box.active {
  border-color: color-mix(in srgb, var(--color-feedback) 75%, #ffffff);
  background: color-mix(in srgb, var(--color-feedback) 65%, #000000);
}

.vulnerability-count-box.mitigated {
  border-color: color-mix(in srgb, var(--color-resolved) 75%, #ffffff);
  background: color-mix(in srgb, var(--color-resolved) 65%, #000000);
}

.vulnerability-count-box strong {
  font-size: 2.35rem;
  line-height: 0.95;
  font-weight: var(--font-weight-bold);
  font-variant-numeric: tabular-nums;
  font-family: var(--font-sans);
  color: #ffffff;
}

.vulnerability-count-box span {
  color: #ffffff;
  font-size: 0.9rem;
  font-weight: var(--font-weight-bold);
}

.vulnerability-count-box small {
  color: rgb(255, 255, 255);
  font-size: 0.74rem;
  font-weight: var(--font-weight-medium);
}

/* Arrow connector */

.vulnerability-flow-arrow {
  color: var(--text-muted);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0.45;
}

.vulnerability-flow-arrow span {
  width: 1.4rem;
  height: 1px;
  background: currentColor;
}

.vulnerability-flow-arrow svg {
  margin-left: -0.15rem;
}

/* â”€â”€ Ticket Workflow â”€â”€ */

.ticket-workflow-grid {
  position: relative;
  z-index: 1;
  flex: 1;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  align-items: stretch;
  gap: var(--space-xs);
}

.workflow-tile {
  min-width: 0;
  min-height: 5.8rem;
  padding: var(--space-xs);
  border: 1px solid var(--tile-border, var(--border));
  border-radius: var(--rounded-sm);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.1), transparent),
    var(--tile-bg, var(--bg-subtle));
  color: var(--tile-color, var(--text-main));
  display: grid;
  grid-template-rows: auto 1fr auto;
  justify-items: center;
  align-items: center;
  gap: var(--space-xs);
  text-align: center;
  transition: transform 0.18s ease-out, box-shadow 0.18s ease-out;
}

@media (prefers-reduced-motion: reduce) {
  .workflow-tile { transition: none; }
}

.workflow-tile:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.workflow-tile svg {
  color: var(--tile-color, var(--text-muted));
  opacity: 0.85;
}

.workflow-tile strong {
  color: var(--tile-color, var(--text-main));
  font-size: 1.55rem;
  line-height: 1;
  font-weight: var(--font-weight-bold);
  font-variant-numeric: tabular-nums;
  font-family: var(--font-sans);
}

.workflow-tile span {
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  color: #ffffff;
  font-size: 0.72rem;
  font-weight: var(--font-weight-semibold);
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Workflow status colors â€” restrained tints */
.workflow-tile.new {
  --tile-bg: var(--workflow-new-bg);
  --tile-border: var(--workflow-new-border);
  --tile-color: var(--workflow-new-text);
}

.workflow-tile.progress {
  --tile-bg: var(--workflow-progress-bg);
  --tile-border: var(--workflow-progress-border);
  --tile-color: var(--workflow-progress-text);
}

.workflow-tile.feedback {
  --tile-bg: var(--workflow-feedback-bg);
  --tile-border: var(--workflow-feedback-border);
  --tile-color: var(--workflow-feedback-text);
}

.workflow-tile.resolved {
  --tile-bg: var(--workflow-resolved-bg);
  --tile-border: var(--workflow-resolved-border);
  --tile-color: var(--workflow-resolved-text);
}

.workflow-tile.closed {
  --tile-bg: var(--workflow-closed-bg);
  --tile-border: var(--workflow-closed-border);
  --tile-color: var(--workflow-closed-text);
}

/* â”€â”€ Severity Distribution â”€â”€ */

.severity-distribution-grid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 1px;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--rounded-md);
  background: var(--border); /* 1px gap separator technique */
}

.severity-distribution-block {
  min-width: 0;
  min-height: 6.6rem;
  padding: var(--space-sm) var(--space-xs);
  background: var(--bg-body);
  color: var(--text-main);
  display: grid;
  grid-template-rows: auto 1fr auto;
  justify-items: center;
  align-items: center;
  gap: var(--space-xs);
  text-align: center;
  transition: background-color 0.18s ease-out;
}

@media (prefers-reduced-motion: reduce) {
  .severity-distribution-block { transition: none; }
}

.severity-distribution-block:hover {
  background: var(--bg-subtle-hover);
}

.severity-distribution-block svg {
  color: var(--tile-color, var(--text-muted));
}

.severity-distribution-block strong {
  color: var(--tile-color, var(--text-main));
  font-size: 1.75rem;
  line-height: 1;
  font-weight: var(--font-weight-bold);
  font-variant-numeric: tabular-nums;
  font-family: var(--font-sans);
}

.severity-distribution-block span {
  width: 100%;
  padding-top: var(--space-xs);
  border-top: 2px solid var(--tile-line, var(--border));
  font-size: 0.72rem;
  font-weight: var(--font-weight-uppercase);
  letter-spacing: 0.05em;
  text-transform: var(--text-transform-uppercase);
  color: var(--tile-color);
}

/* Severity status colors */
.severity-distribution-block.critical {
  --tile-color: #D21404;
  --tile-line: #D21404;
}

.severity-distribution-block.high {
  --tile-color: var(--high-text);
  --tile-line: var(--high);
}

.severity-distribution-block.medium {
  --tile-color: var(--medium-text);
  --tile-line: var(--medium);
}

.severity-distribution-block.low {
  --tile-color: var(--low-text);
  --tile-line: var(--low);
}

.severity-distribution-block.info {
  --tile-color: var(--info-text);
  --tile-line: var(--info);
}

/* â”€â”€ Responsive: Tablet â”€â”€ */

@media (max-width: 1100px) {
  .dashboard-soc-overview {
    grid-template-columns: 1fr;
    gap: var(--space-md);
  }

  .ticket-workflow-grid {
    grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  }

  .severity-distribution-grid {
    grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
    gap: var(--space-sm);
    overflow: visible;
    border: 0;
    border-radius: 0;
    background: transparent;
  }

  .severity-distribution-block {
    border: 1px solid var(--border-subtle);
    border-radius: var(--rounded-sm);
    min-height: 5.5rem;
  }
}

/* â”€â”€ Responsive: Small Tablet â”€â”€ */

@media (max-width: 820px) {
  .vulnerability-flow {
    grid-template-columns: 1fr;
    gap: var(--space-sm);
  }

  .vulnerability-flow-arrow {
    transform: rotate(90deg);
    margin: var(--space-xs) 0;
  }

  .vulnerability-count-box {
    min-height: 5rem;
  }
}

/* â”€â”€ Responsive: Mobile â”€â”€ */

@media (max-width: 640px) {
  .soc-card {
    padding: var(--space-md);
  }

  .soc-card-header h2 {
    font-size: 0.85rem;
  }

  .ticket-workflow-grid,
  .severity-distribution-grid {
    grid-template-columns: 1fr;
    gap: var(--space-xs);
  }

  .workflow-tile,
  .severity-distribution-block {
    min-height: auto;
    padding: var(--space-sm) var(--space-md);
    grid-template-columns: auto 1fr auto;
    grid-template-rows: auto;
    align-items: center;
    justify-items: start;
    text-align: left;
    gap: var(--space-sm);
    border: 1px solid var(--border-subtle);
    border-radius: var(--rounded-sm);
  }

  .workflow-tile svg,
  .severity-distribution-block svg {
    order: 1;
  }

  .workflow-tile span,
  .severity-distribution-block span {
    order: 2;
    padding-top: 0;
    border-top: 0;
    font-size: 0.78rem;
  }

  .workflow-tile strong,
  .severity-distribution-block strong {
    order: 3;
    justify-self: end;
    font-size: 1.35rem;
  }
}

Args.ReplacementContent:
  /* ==========================================
     BASE STYLES & VARIABLES
     ========================================== */
  --bg:          #08090D;
  --surface:     #12141C;
  --surface2:    #181B26;
  --border:      #2A2E3E;
  --border-glow: #3A3F56;
  --text:        #F4F6FB;
  --muted:       #9BA3B8;
  --subtle:      #5C6378;

  --critical:    #FF2E63;
  --high:        #FFA72B;
  --medium:      #FFD60A;
  --low:         #39FF88;
  --info:        #22D3EE;
  --purple:      #C46EFF;

  --critical-bg: rgba(255, 46, 99, 0.14);
  --high-bg:     rgba(255, 167, 43, 0.14);
  --medium-bg:   rgba(255, 214, 10, 0.12);
  --low-bg:      rgba(57, 255, 136, 0.12);
  --info-bg:     rgba(34, 211, 238, 0.12);

  --radius:      12px;
  --radius-sm:   7px;

  /* ==========================================
     DARK THEME (Default & Active)
     ========================================== */
  --bg-body: var(--bg);
  --bg-body-gradient: linear-gradient(135deg, var(--bg) 0%, var(--bg) 100%);
  --bg-card: var(--surface);
  --bg-subtle: var(--surface);
  --bg-subtle-hover: var(--surface2);
  --bg-active: rgba(34, 211, 238, 0.1);
  --bg-active-border: var(--border-glow);
  --bg-input: var(--surface);
  --bg-glass: rgba(18, 20, 28, 0.7);
  --bg-glass-strong: rgba(8, 9, 13, 0.85);
  --bg-elevated: var(--surface2);

  --text-main: var(--text);
  --text-muted: var(--muted);
  --text-soft: var(--subtle);

  --border: var(--border);
  --border-subtle: var(--border);
  --border-strong: var(--border-glow);
  --border-focus: var(--info);

  --primary: var(--info);
  --primary-hover: color-mix(in srgb, var(--info) 80%, #000);
  --primary-text: #04141A;

  /* Button Overrides */
  --btn-primary-bg: var(--primary);
  --btn-primary-text: var(--primary-text);
  --btn-primary-border: var(--primary);
  --btn-primary-hover-bg: var(--primary-hover);
  --btn-secondary-bg: var(--bg-subtle);
  --btn-secondary-text: var(--text-main);
  --btn-secondary-border: var(--border);
  --btn-secondary-hover-bg: var(--bg-subtle-hover);

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.4);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.4), 0 2px 4px -2px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.4), 0 4px 6px -4px rgba(0, 0, 0, 0.4);
  --shadow-popover: 0 20px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.5);

  /* Status Alerts (Contrast Optimized) */
  --danger-text: var(--critical);
  --danger-border: var(--critical-bg);
  --danger-bg: var(--critical-bg);

  --warning-text: var(--high);
  --warning-border: var(--high-bg);
  --warning-bg: var(--high-bg);

  --info-text: var(--info);
  --info-border: var(--info-bg);
  --info-bg: var(--info-bg);

  --connected-text: var(--low);
  --connected-border: var(--low-bg);
  --connected-bg: var(--low-bg);

  --reconnecting-text: var(--high);
  --reconnecting-border: var(--high-bg);
  --reconnecting-bg: var(--high-bg);

  /* Threat Levels Mappings */
  --critical-border: rgba(255, 46, 99, 0.45);
  --critical-text: var(--critical);

  --high-border: rgba(255, 167, 43, 0.4);
  --high-text: var(--high);

  --medium-border: rgba(255, 214, 10, 0.35);
  --medium-text: var(--medium);

  --low-border: rgba(57, 255, 136, 0.4);
  --low-text: var(--low);

  --info-border: rgba(34, 211, 238, 0.4);
  --info-text: var(--info);

  /* Success Status */
  --success: var(--low);
  --success-border: rgba(57, 255, 136, 0.4);
  --success-bg: var(--low-bg);
  --success-text: var(--low);

  /* Unified Ticket Workflow Status Colors */
  --color-new: #2F7DDE;
  --color-progress: #E2A33B;
  --color-feedback: #E2447F;
  --color-resolved: #3FAE76;
  --color-closed: #8A8F98;

  --workflow-new-text: #ffffff;
  --workflow-new-border: color-mix(in srgb, var(--color-new) 75%, #ffffff);
  --workflow-new-bg: color-mix(in srgb, var(--color-new) 65%, #000000);

  --workflow-progress-text: #ffffff;
  --workflow-progress-border: color-mix(in srgb, var(--color-progress) 75%, #ffffff);
  --workflow-progress-bg: color-mix(in srgb, var(--color-progress) 65%, #000000);

  --workflow-feedback-text: #ffffff;
  --workflow-feedback-border: color-mix(in srgb, var(--color-feedback) 75%, #ffffff);
  --workflow-feedback-bg: color-mix(in srgb, var(--color-feedback) 65%, #000000);

  --workflow-resolved-text: #ffffff;
  --workflow-resolved-border: color-mix(in srgb, var(--color-resolved) 75%, #ffffff);
  --workflow-resolved-bg: color-mix(in srgb, var(--color-resolved) 65%, #000000);

  --workflow-closed-text: #ffffff;
  --workflow-closed-border: color-mix(in srgb, var(--color-closed) 75%, #ffffff);
  --workflow-closed-bg: color-mix(in srgb, var(--color-closed) 65%, #000000);
}

/* Redundant selector for specificity */
html[data-theme="dark"] {
  --bg-body: var(--bg);
  --bg-body-gradient: linear-gradient(135deg, var(--bg) 0%, var(--bg) 100%);
  --bg-card: var(--surface);
  --bg-subtle: var(--surface);
  --bg-subtle-hover: var(--surface2);
  --bg-active: rgba(34, 211, 238, 0.1);
  --bg-active-border: var(--border-glow);
