  --text-main: var(--text);
  --text-muted: var(--muted);
  --text-soft: var(--subtle);

  --border: var(--border);
  --border-subtle: var(--border);
  --border-strong: var(--border-glow);
  --border-focus: var(--info);

  --primary: var(--info);
  --primary-hover: color-mix(in srgb, var(--info) 80%, #000);
  --primary-text: #04141A;

Args.TargetContent:
  /* ==========================================
     DARK THEME (Default & Active)
     ========================================== */
  --bg-body: #0a0c10;
  --bg-body-gradient: linear-gradient(135deg, #0a0c10 0%, #0a0c10 100%);
  --bg-card: #13161e;
  --bg-subtle: #13161e;
  --bg-subtle-hover: #1e2330;
  --bg-active: rgba(42, 49, 69, 0.4); /* Subtle highlight matching border */
  --bg-active-border: rgba(42, 49, 69, 0.4);
  --bg-input: #13161e;
  --bg-glass: rgba(19, 22, 30, 0.7);
  --bg-glass-strong: rgba(10, 12, 16, 0.85);
  --bg-elevated: #1e2330;

  --text-main: oklch(96% 0.005 250); /* #f1f4f9 */
  --text-muted: oklch(86% 0.01 250); /* Improved contrast dark theme: #d1d5db */
  --text-soft: oklch(78% 0.015 250); /* Improved contrast dark theme: #9ca8bc */

  --border: #2a3145;
  --border-subtle: #2a3145;
  --border-strong: #2a3145;
  --border-focus: oklch(65% 0.18 250); /* #6366f1 (Indigo 500) */

  --primary: oklch(65% 0.18 250); /* #6366f1 */
  --primary-hover: oklch(58% 0.18 250); /* #4f46e5 */
  --primary-text: oklch(98% 0.005 250); /* #f8fafc */

  /* Button Overrides */
  --btn-primary-bg: var(--primary);
  --btn-primary-text: var(--primary-text);
  --btn-primary-border: var(--primary);
  --btn-primary-hover-bg: var(--primary-hover);
  --btn-secondary-bg: var(--bg-subtle);
  --btn-secondary-text: var(--text-main);
  --btn-secondary-border: var(--border);
  --btn-secondary-hover-bg: var(--bg-subtle-hover);

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.4);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.4), 0 2px 4px -2px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.4), 0 4px 6px -4px rgba(0, 0, 0, 0.4);
  --shadow-popover: 0 20px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.5);

  /* Status Alerts (Contrast Optimized) */
  --danger-text: oklch(74% 0.18 20); /* Coral red */
  --danger-border: oklch(48% 0.18 20 / 0.4);
  --danger-bg: oklch(20% 0.12 20 / 0.3);

  --warning-text: oklch(84% 0.14 85); /* Warm amber */
  --warning-border: oklch(60% 0.14 85 / 0.4);
  --warning-bg: oklch(25% 0.11 85 / 0.3);

  --info-text: oklch(80% 0.12 220); /* Sky blue */
  --info-border: oklch(50% 0.12 220 / 0.4);
  --info-bg: oklch(20% 0.09 220 / 0.3);

  --connected-text: oklch(82% 0.14 145); /* Mint green */
  --connected-border: oklch(55% 0.14 145 / 0.4);
  --connected-bg: oklch(21% 0.10 145 / 0.3);

  --reconnecting-text: oklch(84% 0.14 85);
  --reconnecting-border: oklch(60% 0.14 85 / 0.4);
  --reconnecting-bg: oklch(25% 0.11 85 / 0.3);

  /* Threat Levels Mappings */
  --critical: oklch(74% 0.18 20);
  --critical-border: oklch(48% 0.18 20 / 0.4);
  --critical-bg: oklch(20% 0.12 20 / 0.3);
  --critical-text: oklch(74% 0.18 20);

  --high: oklch(76% 0.17 45);
  --high-border: oklch(50% 0.17 45 / 0.4);
  --high-bg: oklch(22% 0.12 45 / 0.3);
  --high-text: oklch(76% 0.17 45);

  --medium: oklch(84% 0.14 85);
  --medium-border: oklch(60% 0.14 85 / 0.4);
  --medium-bg: oklch(25% 0.11 85 / 0.3);
  --medium-text: oklch(84% 0.14 85);

  --low: oklch(82% 0.14 145);
  --low-border: oklch(55% 0.14 145 / 0.4);
  --low-bg: oklch(21% 0.10 145 / 0.3);
  --low-text: oklch(82% 0.14 145);

  --info: oklch(80% 0.12 220);
  --info-border: oklch(50% 0.12 220 / 0.4);
  --info-bg: oklch(20% 0.09 220 / 0.3);
  --info-text: oklch(80% 0.12 220);

  /* Success Status */
  --success: oklch(82% 0.14 145);
  --success-border: oklch(55% 0.14 145 / 0.4);
  --success-bg: oklch(21% 0.10 145 / 0.3);
  --success-text: oklch(82% 0.14 145);

  /* Unified Ticket Workflow Status Colors */
  --color-new: #3b82f6;
  --color-progress: #eab308;
  --color-feedback: #f97316;
  --color-resolved: #10b981;
  --color-closed: #6b7280;

  --workflow-new-text: #ffffff;
  --workflow-new-border: color-mix(in srgb, var(--color-new) 75%, #ffffff);
  --workflow-new-bg: color-mix(in srgb, var(--color-new) 65%, #000000);

  --workflow-progress-text: #ffffff;
  --workflow-progress-border: color-mix(in srgb, var(--color-progress) 75%, #ffffff);
  --workflow-progress-bg: color-mix(in srgb, var(--color-progress) 65%, #000000);

  --workflow-feedback-text: #ffffff;
  --workflow-feedback-border: color-mix(in srgb, var(--color-feedback) 75%, #ffffff);
  --workflow-feedback-bg: color-mix(in srgb, var(--color-feedback) 65%, #000000);

  --workflow-resolved-text: #ffffff;
  --workflow-resolved-border: color-mix(in srgb, var(--color-resolved) 75%, #ffffff);
  --workflow-resolved-bg: color-mix(in srgb, var(--color-resolved) 65%, #000000);

  --workflow-closed-text: #ffffff;
  --workflow-closed-border: color-mix(in srgb, var(--color-closed) 75%, #ffffff);
  --workflow-closed-bg: color-mix(in srgb, var(--color-closed) 65%, #000000);
}

