const AppSidebarNavItem = ({ item }) => {
  const Icon = item.icon;

  return (
    <button
      type="button"
      className={joinClassNames(
        'nav-item',
        item.className,
        item.active && 'active',
        item.notification && 'notification'
      )}
      onClick={item.onClick}
      disabled={item.disabled}
      aria-current={item.active ? 'page' : undefined}
      title={item.badge > 0 ? `${item.label}: ${item.badge} pending` : item.title || item.label}
    >
      {Icon && <Icon size={16} className="nav-icon" />}
      <span>{item.label}</span>
      {item.badge > 0 && (
        <strong className="nav-badge" aria-label={item.badgeLabel || `${item.badge} pending`}>
          {item.badge > 99 ? '99+' : item.badge}
        </strong>
      )}
    </button>
  );
};

const AppSidebar = ({
  brandIcon: BrandIcon,
  brandLabel,
  footerItems = [],
  navItems = [],
  user,
}) => (
  <aside className="sidebar" aria-label="Primary navigation">
    <div className="logo">
      <span className="logo-mark">
        {BrandIcon && <BrandIcon size={16} />}
      </span>
      <span>
        <strong>{brandLabel}</strong>
      </span>
    </div>

    {user && (
      <div className="user-block">
        <div className="user-name">{user.username}</div>
        <div className="user-role">{user.role === 'admin' ? 'Admin' : 'Viewer'}</div>
      </div>
    )}

    <nav className="nav-section" aria-label="Dashboard sections">
      <div className="nav-label">Menu</div>
      {navItems.map(item => (
        <AppSidebarNavItem key={item.label} item={item} />
      ))}
    </nav>

    <div className="sidebar-footer">
      {footerItems.map(item => (
        <AppSidebarNavItem key={item.label} item={item} />
      ))}
    </div>
  </aside>
);

