.sidebar {
  width: 220px;
  min-height: 100vh;
  background: var(--surface);
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  padding: 20px 0;
  flex-shrink: 0;
  position: sticky;
  top: 0;
  height: 100vh;
}

.logo {
  padding: 0 20px 24px;
  font-size: 18px;
  font-weight: 800;
  letter-spacing: -0.5px;
  color: var(--text);
  border-bottom: 1px solid var(--border);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.logo-mark {
  width: 26px;
  height: 26px;
  border-radius: 7px;
  background: linear-gradient(135deg, var(--info), var(--critical));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  box-shadow: 0 0 14px rgba(34, 211, 238, 0.4);
}

.user-block {
  padding: 12px 20px 16px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 8px;
}

.user-name {
  font-weight: 700;
  font-size: 13px;
  color: var(--text);
}

.user-role {
  font-size: 11px;
  color: var(--info);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: 600;
}

.nav-section {
  padding: 8px 12px 4px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.nav-label {
  font-size: 10px;
  color: var(--subtle);
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 0 8px;
  margin-bottom: 4px;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  color: var(--muted);
  font-size: 13px;
  font-weight: 500;
  transition: all 0.15s;
  text-decoration: none;
  margin-bottom: 2px;
  position: relative;
  background: transparent;
  border: 1px solid transparent;
  width: calc(100% - 4px);
  text-align: left;
}

.nav-item:hover {
  background: var(--surface2);
  color: var(--text);
}

.nav-item.active {
  background: rgba(34, 211, 238, 0.1);
  color: var(--info);
  border: 1px solid rgba(34, 211, 238, 0.35);
  box-shadow: 0 0 16px rgba(34, 211, 238, 0.12) inset;
}

.nav-badge {
  margin-left: auto;
  background: var(--critical);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 10px;
  box-shadow: 0 0 8px rgba(255, 46, 99, 0.6);
}

.nav-icon {
  width: 16px;
  text-align: center;
  font-size: 14px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.sidebar-footer {
  margin-top: auto;
  padding: 16px 12px 0;
  border-top: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.nav-item.danger {
  color: var(--critical);
}

.nav-item.danger:hover {
  background: var(--critical-bg);
  color: var(--critical);
  border-color: rgba(255, 46, 99, 0.2);
}

/* Bell animation for notifications */
.nav-item.notification svg {
  animation: bellPulse 1.9s ease-in-out infinite;
}

@keyframes bellPulse {
  0%, 72%, 100% { transform: rotate(0deg); }
  78% { transform: rotate(-10deg); }
  84% { transform: rotate(9deg); }
  90% { transform: rotate(-5deg); }
  96% { transform: rotate(3deg); }
}

/* Responsive Styles */
@media (max-width: 820px) {
  .sidebar {
    position: sticky;
    top: 0;
    z-index: 160;
    width: 100%;
    min-height: auto;
    height: auto;
    padding: 10px 16px;
    border-right: 0;
    border-bottom: 1px solid var(--border);
    flex-direction: row;
    align-items: center;
    gap: 12px;
    overflow-x: auto;
  }

  .logo {
    padding: 0;
    margin-bottom: 0;
    border-bottom: 0;
  }

  .logo > span:last-child,
  .user-block {
    display: none;
  }

  .logo-mark {
    width: 32px;
    height: 32px;
  }

  .nav-section,
  .sidebar-footer {
    flex: 0 0 auto;
    flex-direction: row;
    align-items: center;
    padding: 0;
    border-top: 0;
    margin-top: 0;
    gap: 4px;
  }

  .sidebar-footer {
    margin-left: auto;
  }

  .nav-label {
    display: none;
  }

  .nav-item {
    width: auto;
    margin-bottom: 0;
    padding: 8px 12px;
  }

  .nav-badge {
    position: absolute;
    top: -4px;
    right: -4px;
    margin-left: 0;
  }
}

@media (max-width: 640px) {
  .nav-item span {
    display: none;
  }
  .nav-item {
    padding: 8px;
  }
}

