const calculatePercentages = (counts = {}) => {
  const items = Object.entries(counts);
  const total = items.reduce((sum, [_, val]) => sum + val, 0);

  if (total === 0) {
    return Object.fromEntries(items.map(([key]) => [key, 0]));
  }

  // Calculate floor values and remainders
  const floorShares = items.map(([key, val]) => {
    const raw = (val / total) * 100;
    const floor = Math.floor(raw);
    const remainder = raw - floor;
    return { key, raw, floor, remainder };
  });

  const allocatedSum = floorShares.reduce((sum, item) => sum + item.floor, 0);
  let difference = 100 - allocatedSum;

  // Sort by remainder descending, then by key to ensure stability
  const sorted = [...floorShares].sort((a, b) => {
