const buildSeverityPercentages = (counts) => {
  const keys = ['Critical', 'High', 'Medium', 'Low', 'Info'];
  const total = keys.reduce((acc, key) => acc + (counts[key] || 0), 0);

  if (total === 0) {
    return Object.fromEntries(keys.map(key => [key, 0]));
  }

  const items = keys.map(key => {
    const raw = ((counts[key] || 0) / total) * 100;
    const integer = Math.floor(raw);
    const remainder = raw - integer;
    return { key, integer, remainder };
  });

  const integerSum = items.reduce((acc, item) => acc + item.integer, 0);
  const difference = 100 - integerSum;

  const sortedItems = [...items].sort((a, b) => {
    if (Math.abs(b.remainder - a.remainder) < 1e-9) {
      return keys.indexOf(a.key) - keys.indexOf(b.key);
    }
    return b.remainder - a.remainder;
  });

  for (let i = 0; i < difference; i++) {
    const itemToIncrement = items.find(item => item.key === sortedItems[i].key);
    if (itemToIncrement) {
      itemToIncrement.integer += 1;
    }
  }

  return Object.fromEntries(items.map(item => [item.key, item.integer]));
};

