   ========================================================================== */
.vuln-panel-title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--muted);
  display: flex;
  align-items: center;
  gap: 6px;
  grid-column: 1 / -1;
  margin-bottom: 10px;
}

