.dashboard-soc-overview-new .stat-card.accent-grey {
  background: #8A8F98;
}

.dashboard-soc-overview-new .stat-label {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.85);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 8px;
}

.dashboard-soc-overview-new .stat-value {
