  color: #fff;
}

.dashboard-soc-overview-new .stat-sub {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.75);
  margin-top: 4px;
}

.dashboard-soc-overview-new .stat-icon {
  font-size: 16px;
  color: rgba(255, 255, 255, 0.9);
  margin-top: 10px;
  display: flex;
  justify-content: flex-end;
}

/* ==========================================================================
   5. SEVERITY & RISK DISTRIBUTION
   ========================================================================== */
.dashboard-soc-overview-new .severity-panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px 20px 18px;
  margin-bottom: 24px;
}

.dashboard-soc-overview-new .severity-panel-title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--muted);
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 18px;
}

.dashboard-soc-overview-new .severity-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
}

.dashboard-soc-overview-new .gauge-card {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.dashboard-soc-overview-new .gauge-svg {
  display: block;
}

.dashboard-soc-overview-new .gauge-value {
  font-size: 26px;
  font-weight: 800;
  letter-spacing: -1px;
  margin-top: -34px;
}

.dashboard-soc-overview-new .gauge-name {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--muted);
  margin-top: 4px;
}

.dashboard-soc-overview-new .gauge-critical .gauge-value {
  color: var(--critical);
  text-shadow: 0 0 16px rgba(255, 46, 99, 0.55);
}

.dashboard-soc-overview-new .gauge-high .gauge-value {
  color: var(--high);
  text-shadow: 0 0 16px rgba(255, 167, 43, 0.5);
}

.dashboard-soc-overview-new .gauge-medium .gauge-value {
  color: var(--medium);
  text-shadow: 0 0 16px rgba(255, 214, 10, 0.45);
}

.dashboard-soc-overview-new .gauge-low .gauge-value {
  color: var(--low);
  text-shadow: 0 0 16px rgba(57, 255, 136, 0.5);
}

.dashboard-soc-overview-new .gauge-info .gauge-value {
  color: var(--info);
  text-shadow: 0 0 16px rgba(34, 211, 238, 0.45);
}

/* â”€â”€ Responsive â”€â”€ */
@media (max-width: 1100px) {
  .dashboard-soc-overview-new .soc-top-row {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 820px) {
  .dashboard-soc-overview-new .vuln-panel {
    flex-direction: column;
  }
  .dashboard-soc-overview-new .vuln-arrow {
    transform: rotate(90deg);
  }
  .dashboard-soc-overview-new .ticket-grid {
    grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  }
  .dashboard-soc-overview-new .severity-grid {
    grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
    gap: 20px;
  }
}
@media (max-width: 640px) {
  .dashboard-soc-overview-new .ticket-grid {
    grid-template-columns: 1fr;
  }
  .dashboard-soc-overview-new .severity-grid {
    grid-template-columns: 1fr;
  }
}

