.hub-page {
  min-height: 100vh;
  background-color: var(--bg-body);
  display: flex;
  flex-direction: column;
}

/* â”€â”€ Top Bar â”€â”€ */
.hub-topbar {
  height: 56px;
  background-color: var(--bg-subtle);
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 1.5rem;
  position: sticky;
  top: 0;
  z-index: 10;
}

.topbar-brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.brand-logo-icon {
  color: var(--primary);
}

.brand-text {
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--text-main);
  letter-spacing: 0.02em;
}

.topbar-user {
  display: flex;
  align-items: center;
  gap: 0.875rem;
}

.user-name {
  font-size: 0.875rem;
  font-weight: 400;
  color: var(--text-main);
}

.role-badge {
  font-size: 0.7rem;
  font-weight: 600;
  padding: 0.125rem 0.5rem;
  border-radius: 9999px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border: 1px solid transparent;
}

.role-badge.admin {
  background-color: rgba(99, 102, 241, 0.12);
  color: var(--primary);
  border-color: rgba(99, 102, 241, 0.3);
}

.role-badge.user {
  background-color: rgba(156, 168, 188, 0.1);
  color: var(--text-muted);
  border-color: rgba(156, 168, 188, 0.2);
}

.btn-logout {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-muted);
  padding: 0.375rem 0.75rem;
  border-radius: var(--rounded-sm);
  font-size: 0.8rem;
  font-weight: 400;
  cursor: pointer;
  transition: all 150ms ease-out;
}

.btn-logout:hover {
  background-color: var(--bg-card);
  border-color: var(--border-strong);
  color: var(--text-main);
}

.btn-logout:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 1px;
}

.btn-logout:active {
  transform: translateY(1px);
}

/* â”€â”€ Content Area â”€â”€ */
.hub-content {
  flex: 1;
  max-width: 900px;
  width: 100%;
  margin: 0 auto;
  padding: 3rem 1.5rem;
  display: flex;
  flex-direction: column;
}

.welcome-section {
  margin-bottom: 2rem;
}

.welcome-back {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin: 0 0 0.5rem 0;
}

.select-workspace-heading {
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--text-main);
  margin: 0;
  letter-spacing: -0.01em;
}

/* â”€â”€ App Grid â”€â”€ */
.app-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.25rem;
  margin-bottom: 3rem;
}

.app-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--rounded-md);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  min-height: 180px;
  cursor: pointer;
  position: relative;
  transition: transform 200ms ease-out, border-color 200ms ease-out, box-shadow 200ms ease-out;
}

.app-card:hover {
  transform: translateY(-3px);
  border-color: var(--accent-color);
  box-shadow: 0 8px 20px -6px rgba(0, 0, 0, 0.5);
}

.app-card:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 1px;
}

.card-top {
  display: flex;
  align-items: center;
  gap: 0.875rem;
  margin-bottom: 1rem;
}

.icon-container {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.app-name {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text-main);
  margin: 0;
}

.app-description {
  font-size: 0.85rem;
  color: var(--text-muted);
  line-height: 1.5;
  margin: 0 0 1.5rem 0;
  flex-grow: 1;
}

.card-status {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: auto;
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.status-dot.healthy {
  background-color: var(--success);
  box-shadow: 0 0 8px var(--success);
}

.status-dot.offline {
  background-color: var(--danger);
  box-shadow: 0 0 8px var(--danger);
}

.status-text {
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--text-muted);
}

/* â”€â”€ Admin Section â”€â”€ */
.admin-section {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.admin-divider {
  height: 1px;
  background-color: var(--border-subtle);
  width: 100%;
  margin-bottom: 0.5rem;
}

.admin-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.btn-admin-nav {
  display: inline-flex;
  align-items: center;
  gap: 0.625rem;
  background-color: var(--bg-card);
  border: 1px solid var(--border-subtle);
  color: var(--text-main);
  padding: 0.625rem 1.25rem;
  border-radius: var(--rounded-md);
  font-size: 0.875rem;
  font-weight: 500;
  text-decoration: none;
  cursor: pointer;
  transition: all 150ms ease-out;
  width: fit-content;
}

.btn-admin-nav:hover {
  background-color: var(--bg-elevated);
  border-color: var(--border-strong);
  transform: translateY(-1px);
}

.btn-admin-nav:active {
  transform: translateY(0);
}

/* â”€â”€ Responsive â”€â”€ */
@media (max-width: 640px) {
  .app-grid {
    grid-template-columns: 1fr;
  }

  .hub-content {
    padding: 2rem 1rem;
  }
}

.users-page {
  min-height: 100vh;
  background-color: var(--bg-body);
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 2rem 1.5rem;
}

.users-container {
  max-width: 600px;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.btn-back {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: transparent;
  border: 1px solid var(--border-subtle);
  color: var(--text-muted);
  padding: 0.5rem 1rem;
  border-radius: var(--rounded-md);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  width: fit-content;
  transition: all 150ms ease-out;
}

.btn-back:hover {
  background-color: var(--bg-card);
  border-color: var(--border-strong);
  color: var(--text-main);
  transform: translateX(-2px);
}

.btn-back:active {
  transform: translateX(0);
}

.users-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--rounded-md);
  padding: 2.5rem;
  box-shadow: var(--shadow-lg);
}

.card-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  margin-bottom: 2rem;
  gap: 1rem;
}

.icon-wrapper {
  width: 64px;
  height: 64px;
  background-color: rgba(99, 102, 241, 0.1);
  color: var(--primary);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.users-heading {
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--text-main);
  margin: 0;
  letter-spacing: -0.01em;
}

.card-body {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.placeholder-text {
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.6;
  margin: 0;
  text-align: center;
}

.info-box {
  background-color: var(--bg-subtle);
  border: 1px solid var(--border-subtle);
  border-radius: var(--rounded-sm);
  padding: 1rem 1.25rem;
}

.info-tag {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--primary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  display: block;
  margin-bottom: 0.375rem;
}

.info-detail {
  font-size: 0.8rem;
  color: var(--text-muted);
  line-height: 1.5;
  margin: 0;
}

