const PORT = process.env.PORT || 3000;
const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret-key-change-me-in-production';
const DATA_DIR = process.env.DATA_DIR ? path.resolve(process.env.DATA_DIR) : path.resolve(__dirname, '..');
const CLIENT_DIST_DIR = process.env.CLIENT_DIST_DIR ? path.resolve(process.env.CLIENT_DIST_DIR) : path.resolve(__dirname, '..', 'dist');
const USERS_FILE_PATH = path.join(DATA_DIR, 'users.json');

const app = express();
app.use(cors());
app.use(express.json());

// â”€â”€ DATABASE CONFIGURATION â”€â”€
const isDbConfigured = Boolean(process.env.DATABASE_URL || process.env.PGHOST || process.env.PGDATABASE);
const USERS_TABLE = 'defectdojo_viewer_users';
let dbPool = null;

if (isDbConfigured) {
  const config = {};
  if (process.env.DATABASE_URL) config.connectionString = process.env.DATABASE_URL;
  const sslMode = String(process.env.PGSSLMODE || '').toLowerCase();
  if (sslMode && sslMode !== 'disable') {
    config.ssl = sslMode === 'no-verify' ? { rejectUnauthorized: false } : true;
  }
  dbPool = new Pool(config);
  console.log('Hub Backend: PostgreSQL database connection initialized');
} else {
  console.log('Hub Backend: Running in file-storage mode (PostgreSQL not configured)');
}

// â”€â”€ JWT HELPERS (CRYPTO-BASED) â”€â”€
function base64UrlEncode(str) {
  return Buffer.from(str)
    .toString('base64')
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_');
}

function base64UrlDecode(str) {
  let base64 = str.replace(/-/g, '+').replace(/_/g, '/');
  while (base64.length % 4) {
    base64 += '=';
  }
  return Buffer.from(base64, 'base64').toString('utf8');
}

function signJwt(payload, secret, expiresInSeconds = 3600) {
  const header = { alg: 'HS256', typ: 'JWT' };
  const exp = Math.floor(Date.now() / 1000) + expiresInSeconds;
  const fullPayload = { ...payload, exp };

  const encodedHeader = base64UrlEncode(JSON.stringify(header));
  const encodedPayload = base64UrlEncode(JSON.stringify(fullPayload));

  const signature = crypto
    .createHmac('sha256', secret)
    .update(`${encodedHeader}.${encodedPayload}`)
    .digest('base64')
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_');

  return `${encodedHeader}.${encodedPayload}.${signature}`;
}

function verifyJwt(token, secret) {
  try {
    const parts = token.split('.');
    if (parts.length !== 3) return null;

    const [encodedHeader, encodedPayload, signature] = parts;

    const expectedSignature = crypto
      .createHmac('sha256', secret)
      .update(`${encodedHeader}.${encodedPayload}`)
      .digest('base64')
      .replace(/=/g, '')
      .replace(/\+/g, '-')
      .replace(/\//g, '_');

    if (signature !== expectedSignature) return null;

    const payload = JSON.parse(base64UrlDecode(encodedPayload));
    if (payload.exp && Date.now() / 1000 > payload.exp) {
      return null; // Expired
    }

    return payload;
  } catch {
    return null;
  }
}

// â”€â”€ PASSWORD HELPERS (MATCHES EXISTING ALG) â”€â”€
function hashPassword(password, salt = crypto.randomBytes(16).toString('hex')) {
  const hash = crypto.pbkdf2Sync(password, salt, 1000, 64, 'sha512').toString('hex');
  return { salt, hash };
}

function verifyPassword(password, hash, salt) {
  const verifyHash = crypto.pbkdf2Sync(password, salt, 1000, 64, 'sha512').toString('hex');
  return hash === verifyHash;
}

// â”€â”€ USER MANAGEMENT HELPERS â”€â”€
function createDefaultAdminUser() {
  const { salt, hash } = hashPassword('admin');
  return {
    username: 'admin',
    salt,
    hash,
    email: '',
    role: 'admin',
    products: [],
    status: 'active',
    lastLoginAt: ''
  };
}

function normalizeUserRecord(user = {}) {
  return {
    username: String(user.username || '').trim(),
    salt: user.salt || '',
    hash: user.hash || user.password_hash || '',
    email: String(user.email || '').trim(),
    role: String(user.role || 'viewer').trim() || 'viewer',
    products: Array.isArray(user.products) ? user.products : [],
    status: String(user.status || 'active').trim().toLowerCase() === 'suspended' ? 'suspended' : 'active',
    lastLoginAt: user.lastLoginAt || user.last_login_at || ''
  };
}

function buildPublicUser(user = {}) {
  const normalized = normalizeUserRecord(user);
  return {
    username: normalized.username,
    email: normalized.email,
    role: normalized.role,
    products: normalized.products,
    status: normalized.status,
    accountStatus: normalized.status,
    lastLoginAt: normalized.lastLoginAt
  };
}

// Read users from disk
function readUsersFromDisk() {
  if (fs.existsSync(USERS_FILE_PATH)) {
    try {
      const data = JSON.parse(fs.readFileSync(USERS_FILE_PATH, 'utf8'));
      return Array.isArray(data) ? data.map(normalizeUserRecord).filter(u => u.username) : [];
    } catch (err) {
      console.error('Error reading users from disk:', err);
    }
  }
  return [];
}

// Load users (from PostgreSQL if configured, otherwise disk)
async function loadUsers() {
  let users = [];
  if (dbPool) {
    try {
      const { rows } = await dbPool.query(`
        SELECT username, salt, password_hash, email, role, products, status, last_login_at
        FROM ${USERS_TABLE}
        ORDER BY username
      `);
      users = rows.map(row => ({
        username: row.username,
        salt: row.salt,
        hash: row.password_hash,
        email: row.email || '',
        role: row.role,
        products: Array.isArray(row.products) ? row.products : [],
        status: row.status || 'active',
        lastLoginAt: row.last_login_at ? new Date(row.last_login_at).toISOString() : ''
      }));
    } catch (err) {
      console.error('Error loading users from PostgreSQL, falling back to disk:', err);
      users = readUsersFromDisk();
    }
  } else {
    users = readUsersFromDisk();
  }

  // Ensure default admin user exists if empty
  if (users.length === 0) {
    const defaultAdmin = createDefaultAdminUser();
    users.push(defaultAdmin);
    await saveUsers(users);
  }

  return users.map(normalizeUserRecord);
}

// Save users (to PostgreSQL if configured, otherwise disk)
async function saveUsers(usersList) {
  const normalized = usersList.filter(u => u?.username).map(normalizeUserRecord);

  if (dbPool) {
    try {
      // Begin transaction
      const client = await dbPool.connect();
      try {
        await client.query('BEGIN');

        // Delete users not in list
        await client.query(
          `DELETE FROM ${USERS_TABLE} WHERE NOT (username = ANY($1::text[]))`,
          [normalized.map(u => u.username)]
        );

        // Insert or update users
        for (const user of normalized) {
          await client.query(`
            INSERT INTO ${USERS_TABLE} (username, salt, password_hash, email, role, products, status, last_login_at)
            VALUES ($1, $2, $3, $4, $5, $6::jsonb, $7, $8)
            ON CONFLICT (username)
            DO UPDATE SET
              salt = EXCLUDED.salt,
              password_hash = EXCLUDED.password_hash,
              email = EXCLUDED.email,
              role = EXCLUDED.role,
              products = EXCLUDED.products,
              status = EXCLUDED.status,
              last_login_at = EXCLUDED.last_login_at
          `, [
            user.username,
            user.salt,
            user.hash,
            user.email,
            user.role,
            JSON.stringify(user.products),
            user.status,
            user.lastLoginAt ? new Date(user.lastLoginAt) : null
          ]);
        }

        await client.query('COMMIT');
      } catch (err) {
        await client.query('ROLLBACK');
        throw err;
      } finally {
        client.release();
      }
      return;
    } catch (err) {
      console.error('Error saving users to PostgreSQL, saving to disk instead:', err);
    }
  }

  // File fallback
  fs.writeFileSync(USERS_FILE_PATH, JSON.stringify(normalized, null, 2), 'utf8');
}

// â”€â”€ EXPRESS AUTHENTICATION MIDDLEWARES â”€â”€
function authenticateJwt(req, res, next) {
  const authHeader = req.headers.authorization || '';
  const token = authHeader.replace('Bearer ', '').trim();

  if (!token) {
    return res.status(401).json({ error: 'Unauthorized: Missing token' });
  }

  const payload = verifyJwt(token, JWT_SECRET);
  if (!payload) {
    return res.status(401).json({ error: 'Unauthorized: Invalid or expired token' });
  }

  req.user = payload;
  next();
}

function requireAdmin(req, res, next) {
  if (req.user?.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden: Admin access required' });
  }
  next();
}

// â”€â”€ API ROUTES â”€â”€

// Auth - Login
app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: 'Username and password are required' });
  }

  try {
    const users = await loadUsers();
    const userIndex = users.findIndex(u => u.username === username);
    const user = userIndex >= 0 ? users[userIndex] : null;

    if (!user || !verifyPassword(password, user.hash, user.salt)) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    if (user.status === 'suspended') {
      return res.status(403).json({ error: 'User account is suspended' });
    }

    // Update login timestamp
    user.lastLoginAt = new Date().toISOString();
    users[userIndex] = user;
    await saveUsers(users);

    // Generate JWT
    const payload = {
      username: user.username,
      email: user.email,
      role: user.role,
      products: user.products,
      status: user.status
    };
    const token = signJwt(payload, JWT_SECRET, 3600); // 1 hour token

    res.json({
      token,
      user: buildPublicUser(user)
    });
  } catch (err) {
    console.error('Login error:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Auth - Logout
app.post('/api/logout', (req, res) => {
  // Stateless JWT logout is handled on client-side by purging localstorage
  res.json({ message: 'Logged out successfully' });
});

// Users - List all users (Admins only)
app.get('/api/users', authenticateJwt, requireAdmin, async (req, res) => {
  try {
    const users = await loadUsers();
    res.json(users.map(buildPublicUser));
  } catch (err) {
    console.error('List users error:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users - Create or Update (Admins only)
app.post('/api/users', authenticateJwt, requireAdmin, async (req, res) => {
  const { username, password, role, products, email, status } = req.body;
  if (!username || !role) {
    return res.status(400).json({ error: 'Username and role are required' });
  }

  try {
    const users = await loadUsers();
    const existingIndex = users.findIndex(u => u.username === username);

    const nextStatus = String(status || 'active').trim().toLowerCase() === 'suspended' ? 'suspended' : 'active';
    const nextEmail = String(email || '').trim();
    const nextProducts = Array.isArray(products) ? products : [];

    // Prevent suspending yourself
    if (req.user.username === username && nextStatus === 'suspended') {
      return res.status(400).json({ error: 'Cannot suspend your own account' });
    }

    if (existingIndex >= 0) {
      // Update existing user
      const existingUser = users[existingIndex];
      users[existingIndex] = {
        ...existingUser,
        email: nextEmail,
        role,
        products: nextProducts,
        status: nextStatus
      };
      if (password) {
        const { salt, hash } = hashPassword(password);
        users[existingIndex].salt = salt;
        users[existingIndex].hash = hash;
      }
    } else {
      // Create new user
      if (!password) {
        return res.status(400).json({ error: 'Password is required for new users' });
      }
      const { salt, hash } = hashPassword(password);
      users.push({
        username,
        salt,
        hash,
        email: nextEmail,
        role,
        products: nextProducts,
        status: nextStatus,
        lastLoginAt: ''
      });
    }

    await saveUsers(users);
    const saved = users.find(u => u.username === username);
    res.json({
      message: 'User saved successfully',
      user: buildPublicUser(saved)
    });
  } catch (err) {
    console.error('Save user error:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users - Delete (Admins only)
app.delete('/api/users/:username', authenticateJwt, requireAdmin, async (req, res) => {
  const { username } = req.params;

  try {
    let users = await loadUsers();

    // Prevent deleting the last admin
    if (username === 'admin' && users.filter(u => u.role === 'admin').length <= 1) {
      return res.status(400).json({ error: 'Cannot delete the last administrator account' });
    }

    // Prevent deleting yourself
    if (req.user.username === username) {
      return res.status(400).json({ error: 'Cannot delete your own account' });
    }

    const initialLength = users.length;
    users = users.filter(u => u.username !== username);

    if (users.length === initialLength) {
      return res.status(404).json({ error: 'User not found' });
    }

    await saveUsers(users);
    res.json({ message: 'User deleted successfully' });
  } catch (err) {
    console.error('Delete user error:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Health check endpoint
app.get('/api/health', (req, res) => {
  res.json({
    ok: true,
    storage: dbPool ? 'postgresql' : 'json'
  });
});

// â”€â”€ SERVE STATIC REACT FILES â”€â”€
app.use(express.static(CLIENT_DIST_DIR));

// Fallback to React app index.html for frontend routing
app.get('*', (req, res) => {
  const indexPath = path.join(CLIENT_DIST_DIR, 'index.html');
  if (fs.existsSync(indexPath)) {
    res.sendFile(indexPath);
  } else {
    res.status(404).send('Not Found');
  }
});

// Start Server
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Hub Service backend listening on 0.0.0.0:${PORT}`);
});

# Rate limiting zone for auth endpoints
limit_req_zone $binary_remote_addr zone=login_limit:10m rate=5r/s;

server {
    listen 80;
    server_name localhost;

    # Security Headers
    add_header X-Frame-Options "SAMEORIGIN" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-XSS-Protection "1; mode=block" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;

    # Enable gzip compression
    gzip on;
    gzip_types text/plain text/css application/json application/javascript text/xml application/xml application/xml+rss text/javascript;
    gzip_min_length 1000;

    # â”€â”€ 1. HUB SERVICE (ROOT) â”€â”€
    location / {
        proxy_pass http://hub:3000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection 'upgrade';
        proxy_set_header Host $host;
        proxy_cache_bypass $http_upgrade;

        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    # Rate-limit the Hub login endpoint to prevent brute-force attacks
    location = /api/login {
        limit_req zone=login_limit burst=10 nodelay;

        proxy_pass http://hub:3000/api/login;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    # â”€â”€ 2. DEFECTDOJO VIEWER SERVICE â”€â”€
    # Note the trailing slash on both location and proxy_pass to strip /defectdojo/ prefix
    location /defectdojo/ {
        proxy_pass http://defectdojo:3001/;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection 'upgrade';
        proxy_set_header Host $host;
        proxy_cache_bypass $http_upgrade;

        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # Adjust cookies path if the backend uses session cookies (fallback safety)
        proxy_cookie_path / /defectdojo;
    }

    # â”€â”€ 3. WAZUH VIEWER SERVICE (MOCKUP) â”€â”€
    # Note the trailing slash on both location and proxy_pass to strip /wazuh/ prefix
    location /wazuh/ {
        proxy_pass http://wazuh:3002/;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection 'upgrade';
        proxy_set_header Host $host;
        proxy_cache_bypass $http_upgrade;

        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    # Error handling configuration
    error_page 502 /502.html;
    location = /502.html {
        root /usr/share/nginx/html;
        internal;
        # Inline custom styled error message fitting the design system
        return 502 '{"error": "Bad Gateway - The requested middleware service is temporarily offline or rebuilding. Please try again in a few moments."}';
    }
}

