:root {
  /* Surface Palette */
  --bg-body: #0f1624;
  --bg-card: #172033;
  --bg-subtle: #131a2a;
  --bg-elevated: #1e293f;

  /* Text */
  --text-main: #f1f4f9;
  --text-muted: #9ca8bc;

  /* Borders */
  --border: #2d3748;
  --border-subtle: #212b3d;
  --border-strong: #3b475e;

  /* Primary (Green Accent for Wazuh) */
  --primary: #22c55e;
  --primary-hover: #16a34a;
  --primary-text: #f8fafc;

  /* Semantic status colors */
  --success: #22c55e;
  --success-bg: rgba(34, 197, 94, 0.12);
  --warning: #f59e0b;
  --warning-bg: rgba(245, 158, 11, 0.12);
  --danger: #ef4444;
  --danger-bg: rgba(239, 68, 68, 0.12);
  --info: #3b82f6;
  --info-bg: rgba(59, 130, 246, 0.12);

  /* Threat Levels */
  --level-low: #3b82f6;
  --level-medium: #f59e0b;
  --level-high: #ea580c;
  --level-critical: #ef4444;

  /* Typography */
  --font-sans: 'Prompt', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Consolas, 'Liberation Mono', monospace;

  /* Radii */
  --rounded-sm: 0.5rem;
  --rounded-md: 0.75rem;

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.4);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.4), 0 2px 4px -2px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.4), 0 4px 6px -4px rgba(0, 0, 0, 0.4);
}

/* â”€â”€ Reset & Core â”€â”€ */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  font-family: var(--font-sans);
  font-weight: 300;
  line-height: 1.5;
  letter-spacing: 0.015em;
  color: var(--text-main);
  background-color: var(--bg-body);
  -webkit-font-smoothing: antialiased;
}

button, input, select, textarea {
  font: inherit;
  color: inherit;
  background: transparent;
  border: none;
}

a {
  color: inherit;
  text-decoration: none;
}

/* â”€â”€ App Shell Layout â”€â”€ */
.app-shell {
  display: flex;
  min-height: 100vh;
}

/* App Sidebar */
.app-sidebar {
  width: 240px;
  background-color: var(--bg-subtle);
  border-right: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
}

.sidebar-brand {
  height: 56px;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0 1.25rem;
  border-bottom: 1px solid var(--border-subtle);
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--text-main);
}

.sidebar-brand-mark {
  color: var(--primary);
  display: flex;
  align-items: center;
}

.sidebar-user {
  padding: 1rem 1.25rem;
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
}

.sidebar-user span {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-main);
}

.sidebar-user small {
  font-size: 0.75rem;
  color: var(--text-muted);
  text-transform: capitalize;
}

.sidebar-nav {
  flex: 1;
  padding: 1rem 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.sidebar-nav-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.625rem 0.75rem;
  border-radius: var(--rounded-sm);
  font-size: 0.875rem;
  font-weight: 400;
  color: var(--text-muted);
  cursor: pointer;
  text-align: left;
  transition: all 150ms ease-out;
}

.sidebar-nav-item:hover {
  background-color: rgba(255, 255, 255, 0.03);
  color: var(--text-main);
}

.sidebar-nav-item.active {
  background-color: rgba(34, 197, 94, 0.08);
  color: var(--primary);
  font-weight: 500;
}

.sidebar-nav-item.danger:hover {
  background-color: rgba(239, 68, 68, 0.1);
  color: #ef4444;
}

.sidebar-footer {
  padding: 1rem 0.75rem;
  border-top: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

/* Main Viewport */
.main-viewport {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  max-height: 100vh;
}

/* Page Frame */
.page-frame {
  padding: 2rem;
  max-width: 1200px;
  width: 100%;
  margin: 0 auto;
}

.page-header {
  display: flex;
  justify-content: space-between;
