}

.page-actions {
  display: flex;
  gap: 0.75rem;
}

/* â”€â”€ UI Components â”€â”€ */

/* Buttons */
.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background-color: var(--primary);
  color: var(--bg-body);
  font-weight: 500;
