/* Modal Overlay */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(10, 10, 18, 0.85);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  padding: 1.5rem;
}

.modal-content {
  background-color: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--rounded-md);
  width: 100%;
  max-width: 700px;
  max-height: 85vh;
  overflow-y: auto;
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
}

.modal-header {
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: var(--bg-subtle);
}

.modal-header h2 {
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--text-main);
}

.modal-close {
  cursor: pointer;
  color: var(--text-muted);
  transition: color 150ms ease-out;
}

.modal-close:hover {
  color: var(--text-main);
}

.modal-body {
  padding: 1.5rem;
  flex: 1;
}

.modal-footer {
  padding: 1rem 1.5rem;
  border-top: 1px solid var(--border-subtle);
  display: flex;
  justify-content: flex-end;
  gap: 0.75rem;
  background-color: var(--bg-subtle);
}

/* Responsive */
@media (max-width: 960px) {
  .card-grid-4 {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .app-sidebar {
    width: 60px;
  }
  .app-sidebar .sidebar-brand span:not(.sidebar-brand-mark),
  .app-sidebar .sidebar-user,
  .app-sidebar .sidebar-nav-item span,
  .app-sidebar .sidebar-footer button span {
    display: none;
  }
  .card-grid-4 {
    grid-template-columns: 1fr;
  }
  .card-grid-2 {
    grid-template-columns: 1fr;
  }
  .table-toolbar {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.75rem;
  }
  .search-input {
    width: 100%;
  }
}

