  --low: #22c55e;
  --low-border: rgba(34, 197, 94, 0.3);
  --low-bg: rgba(34, 197, 94, 0.15);
  --low-text: #22c55e;

  --info: #22d3ee;
  --info-border: rgba(34, 211, 238, 0.3);
  --info-bg: rgba(34, 211, 238, 0.15);
  --info-text: #22d3ee;

