  --workflow-feedback-text: var(--danger-text);
  --workflow-feedback-border: var(--danger-border);
  --workflow-feedback-bg: var(--danger-bg);

  --workflow-resolved-text: var(--success-text);
  --workflow-resolved-border: var(--success-border);
  --workflow-resolved-bg: var(--success-bg);

  --workflow-closed-text: var(--text-soft);
  --workflow-closed-border: var(--border-subtle);
  --workflow-closed-bg: var(--bg-subtle);

