--workflow-progress-border: color-mix(in srgb, var(--color-progress) 75%, #ffffff);
--workflow-progress-bg: color-mix(in srgb, var(--color-progress) 55%, #000000);

--workflow-feedback-text: #ffffff;
--workflow-feedback-border: color-mix(in srgb, var(--color-feedback) 75%, #ffffff);
--workflow-feedback-bg: color-mix(in srgb, var(--color-feedback) 55%, #000000);

--workflow-resolved-text: #ffffff;
--workflow-resolved-border: color-mix(in srgb, var(--color-resolved) 75%, #ffffff);
--workflow-resolved-bg: color-mix(in srgb, var(--color-resolved) 55%, #000000);

Args.ReplacementContent:
.vulnerability-count-box.active {
  border-color: color-mix(in srgb, var(--color-feedback) 75%, #ffffff);
  background: color-mix(in srgb, var(--color-feedback) 65%, #000000);
}

.vulnerability-count-box.mitigated {
  border-color: color-mix(in srgb, var(--color-resolved) 75%, #ffffff);
  background: color-mix(in srgb, var(--color-resolved) 65%, #000000);
}

.vulnerability-count-box strong {
  font-size: 2.35rem;
  line-height: 0.95;
  font-weight: var(--font-weight-bold);
  font-variant-numeric: tabular-nums;
  font-family: var(--font-sans);
  color: #ffffff;
}

.vulnerability-count-box span {
  color: #ffffff;
  font-size: 0.9rem;
  font-weight: var(--font-weight-bold);
}

.vulnerability-count-box small {
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.74rem;
  font-weight: var(--font-weight-medium);
}

Args.TargetContent:
.vulnerability-count-box.active {
  border-color: var(--high-border);
  background: var(--high-bg);
}

.vulnerability-count-box.mitigated {
  border-color: var(--success-border);
  background: var(--success-bg);
}

.vulnerability-count-box strong {
  font-size: 2.35rem;
  line-height: 0.95;
  font-weight: var(--font-weight-bold);
  font-variant-numeric: tabular-nums;
  font-family: var(--font-sans);
}

.vulnerability-count-box.active strong {
  color: var(--high-text);
}

.vulnerability-count-box.mitigated strong {
  color: var(--success-text);
}

.vulnerability-count-box span {
  color: var(--text-main);
  font-size: 0.9rem;
  font-weight: var(--font-weight-bold);
}

.vulnerability-count-box small {
  color: var(--text-muted);
  font-size: 0.74rem;
  font-weight: var(--font-weight-medium);
}

Args.ReplacementContent:
border-bottom: 1px solid var(--border);
background: color-mix(in oklab, oklch(21% .034 264.665) 80%, transparent);
backdrop-filter: blur(14px);

Args.TargetContent:
border-bottom: 1px solid var(--border);
background: var(--bg-glass-strong);
backdrop-filter: blur(14px);

Args.ReplacementContent:
border-right: 1px solid var(--border);
background: color-mix(in oklab, oklch(21% .034 264.665) 80%, transparent);
backdrop-filter: blur(16px);

Args.TargetContent:
border-right: 1px solid var(--border);
background: var(--bg-glass-strong);
backdrop-filter: blur(16px);
